# Now let me implement the full walk application
# I'll use pure Go stdlib - syscall for raw mode, os/io for file operations

cat > /workspace/src/main.go << 'GOEOF'
package main

import (
	"bufio"
	"fmt"
	"io"
	"io/fs"
	"os"
	"os/exec"
	"os/signal"
	"path/filepath"
	"sort"
	"strings"
	"syscall"
	"unicode/utf8"
	"unsafe"
)

const version = "v1.13.0"

// Terminal escape codes
const (
	clear          = "\033[H\033[J"
	clearLine      = "\033[K"
	hideCursor     = "\033[?25l"
	showCursor     = "\033[?25h"
	altScreen      = "\033[?1049h"
	mainScreen     = "\033[?1049l"
	resetStyle     = "\033[0m"
	bold           = "\033[1m"
	dim            = "\033[2m"
	reverseVideo   = "\033[7m"
	bracketedPaste = "\033[?2004h"
)

func moveTo(row, col int) string {
	return fmt.Sprintf("\033[%d;%dH", row, col)
}

func setFg(color int) string {
	return fmt.Sprintf("\033[38;5;%dm", color)
}

func setBg(color int) string {
	return fmt.Sprintf("\033[48;5;%dm", color)
}

// Winsize represents the terminal window size
type Winsize struct {
	Row    uint16
	Col    uint16
	Xpixel uint16
	Ypixel uint16
}

func getTermSize() (int, int) {
	ws := &Winsize{}
	retCode, _, errno := syscall.Syscall(
		syscall.SYS_IOCTL,
		uintptr(syscall.Stdout),
		uintptr(syscall.TIOCGWINSZ),
		uintptr(unsafe.Pointer(ws)),
	)
	if int(retCode) == -1 {
		_ = errno
		return 80, 24
	}
	return int(ws.Col), int(ws.Row)
}

type Termios = syscall.Termios

func setRawMode(fd int) (*Termios, error) {
	var oldState Termios
	if _, _, err := syscall.Syscall6(syscall.SYS_IOCTL, uintptr(fd), syscall.TCGETS, uintptr(unsafe.Pointer(&oldState)), 0, 0, 0); err != 0 {
		return nil, err
	}
	newState := oldState
	// Set raw mode
	newState.Iflag &^= syscall.IXON | syscall.ICRNL | syscall.BRKINT | syscall.INPCK | syscall.ISTRIP
	newState.Oflag &^= syscall.OPOST
	newState.Cflag |= syscall.CS8
	newState.Lflag &^= syscall.ECHO | syscall.ECHONL | syscall.ICANON | syscall.ISIG | syscall.IEXTEN
	newState.Cc[syscall.VMIN] = 1
	newState.Cc[syscall.VTIME] = 0
	if _, _, err := syscall.Syscall6(syscall.SYS_IOCTL, uintptr(fd), syscall.TCSETS, uintptr(unsafe.Pointer(&newState)), 0, 0, 0); err != 0 {
		return nil, err
	}
	return &oldState, nil
}

func restoreMode(fd int, state *Termios) error {
	_, _, err := syscall.Syscall6(syscall.SYS_IOCTL, uintptr(fd), syscall.TCSETS, uintptr(unsafe.Pointer(state)), 0, 0, 0)
	if err != 0 {
		return err
	}
	return nil
}

// Key codes
type Key int

const (
	KeyNone Key = iota
	KeyUp
	KeyDown
	KeyLeft
	KeyRight
	KeyShiftUp
	KeyShiftDown
	KeyEnter
	KeyBackspace
	KeyEsc
	KeyCtrlC
	KeySpace
	KeySlash
	KeyDot
	KeyD
	KeyDelete
	KeyY
	KeyU
	KeyQ
	KeyH
	KeyJ
	KeyK
	KeyL
	KeyQuestion
	KeyOther
)

func readKey(r io.Reader) (Key, rune, error) {
	buf := make([]byte, 1)
	_, err := r.Read(buf)
	if err != nil {
		return KeyNone, 0, err
	}
	b := buf[0]

	switch b {
	case 3: // Ctrl+C
		return KeyCtrlC, 0, nil
	case 8, 127: // Backspace
		return KeyBackspace, 0, nil
	case 13: // Enter
		return KeyEnter, 0, nil
	case 27: // Escape sequence
		// Read more bytes if available
		extra := make([]byte, 6)
		// Try to read with timeout
		n, _ := r.Read(extra[:1])
		if n == 0 {
			return KeyEsc, 0, nil
		}
		if extra[0] == '[' {
			n, _ = r.Read(extra[1:2])
			if n == 0 {
				return KeyEsc, 0, nil
			}
			switch extra[1] {
			case 'A': // Up arrow
				return KeyUp, 0, nil
			case 'B': // Down arrow
				return KeyDown, 0, nil
			case 'C': // Right arrow
				return KeyRight, 0, nil
			case 'D': // Left arrow
				return KeyLeft, 0, nil
			case '1': // possibly shift+arrow
				n, _ = r.Read(extra[2:3])
				if n > 0 && extra[2] == ';' {
					n, _ = r.Read(extra[3:4])
					if n > 0 && extra[3] == '2' {
						n, _ = r.Read(extra[4:5])
						if n > 0 {
							switch extra[4] {
							case 'A':
								return KeyShiftUp, 0, nil
							case 'B':
								return KeyShiftDown, 0, nil
							}
						}
					}
				}
			case '3': // Delete key: ESC[3~
				n, _ = r.Read(extra[2:3])
				if n > 0 && extra[2] == '~' {
					return KeyDelete, 0, nil
				}
			case '5': // Page up: ESC[5~
				r.Read(extra[2:3])
				return KeyShiftUp, 0, nil
			case '6': // Page down: ESC[6~
				r.Read(extra[2:3])
				return KeyShiftDown, 0, nil
			}
		}
		return KeyEsc, 0, nil
	case 32: // Space
		return KeySpace, 0, nil
	case '/':
		return KeySlash, '/', nil
	case '.':
		return KeyDot, '.', nil
	case 'd':
		return KeyD, 'd', nil
	case 'y':
		return KeyY, 'y', nil
	case 'u':
		return KeyU, 'u', nil
	case 'q':
		return KeyQ, 'q', nil
	case 'h':
		return KeyH, 'h', nil
	case 'j':
		return KeyJ, 'j', nil
	case 'k':
		return KeyK, 'k', nil
	case 'l':
		return KeyL, 'l', nil
	case '?':
		return KeyQuestion, '?', nil
	default:
		if b >= 32 && b < 128 {
			return KeyOther, rune(b), nil
		}
		if b >= 0x80 {
			// UTF-8 multi-byte
			var bytes []byte
			bytes = append(bytes, b)
			// Read remaining bytes
			if b&0xE0 == 0xC0 {
				more := make([]byte, 1)
				r.Read(more)
				bytes = append(bytes, more...)
			} else if b&0xF0 == 0xE0 {
				more := make([]byte, 2)
				r.Read(more)
				bytes = append(bytes, more...)
			} else if b&0xF8 == 0xF0 {
				more := make([]byte, 3)
				r.Read(more)
				bytes = append(bytes, more...)
			}
			r, _ := utf8.DecodeRune(bytes)
			return KeyOther, r, nil
		}
	}
	return KeyOther, rune(b), nil
}

func listDir(dir string, showHidden, dirOnly bool) ([]fs.DirEntry, error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, err
	}
	var result []fs.DirEntry
	for _, e := range entries {
		name := e.Name()
		if !showHidden && strings.HasPrefix(name, ".") {
			continue
		}
		if dirOnly && !e.IsDir() {
			continue
		}
		result = append(result, e)
	}
	// Sort: dirs first, then files, both alphabetically
	sort.Slice(result, func(i, j int) bool {
		iDir := result[i].IsDir()
		jDir := result[j].IsDir()
		if iDir != jDir {
			return iDir
		}
		return strings.ToLower(result[i].Name()) < strings.ToLower(result[j].Name())
	})
	return result, nil
}

type DeletedEntry struct {
	path string
	dir  string
}

type App struct {
	tty        *os.File
	ttyFd      int
	origState  *Termios
	w          *bufio.Writer

	cwd        string
	entries    []fs.DirEntry
	cursor     int
	offset     int

	showHidden bool
	dirOnly    bool
	preview    bool
	withBorder bool
	icons      bool
	fuzzy      bool
	fuzzyMode  bool
	search     string

	previewScroll int

	mainColor int // ansi 256 color

	deleted    []DeletedEntry

	showHelp   bool

	width      int
	height     int

	statusBar  string // WALK_STATUS_BAR expression
}

func (a *App) readDir() {
	entries, err := listDir(a.cwd, a.showHidden, a.dirOnly)
	if err != nil {
		a.entries = nil
		return
	}
	a.entries = entries
	if a.cursor >= len(a.entries) {
		a.cursor = len(a.entries) - 1
	}
	if a.cursor < 0 {
		a.cursor = 0
	}
}

func (a *App) filteredEntries() []fs.DirEntry {
	if a.search == "" {
		return a.entries
	}
	search := strings.ToLower(a.search)
	var result []fs.DirEntry
	for _, e := range a.entries {
		name := strings.ToLower(e.Name())
		if fuzzyMatch(name, search) {
			result = append(result, e)
		}
	}
	return result
}

// Simple fuzzy match: all chars of pattern appear in order in s
func fuzzyMatch(s, pattern string) bool {
	if pattern == "" {
		return true
	}
	j := 0
	for i := 0; i < len(s) && j < len(pattern); i++ {
		if s[i] == pattern[j] {
			j++
		}
	}
	return j == len(pattern)
}

func (a *App) currentEntry() fs.DirEntry {
	filtered := a.filteredEntries()
	if len(filtered) == 0 {
		return nil
	}
	if a.cursor >= len(filtered) {
		return filtered[len(filtered)-1]
	}
	if a.cursor < 0 {
		return filtered[0]
	}
	return filtered[a.cursor]
}

func (a *App) clampCursor() {
	filtered := a.filteredEntries()
	n := len(filtered)
	if n == 0 {
		a.cursor = 0
		return
	}
	if a.cursor < 0 {
		a.cursor = 0
	}
	if a.cursor >= n {
		a.cursor = n - 1
	}
}

func (a *App) render() {
	a.width, a.height = getTermSize()

	var sb strings.Builder
	sb.WriteString(hideCursor)
	sb.WriteString(moveTo(1, 1))

	listWidth := a.width
	if a.preview {
		listWidth = a.width / 2
	}

	if a.showHelp {
		a.renderHelp(&sb)
		sb.WriteString(showCursor)
		a.w.WriteString(sb.String())
		a.w.Flush()
		return
	}

	// Render header: current path
	header := a.cwd
	if a.fuzzyMode || (a.fuzzy && a.search != "") {
		header = a.cwd + "/" + a.search
	}

	// Truncate header if too long
	maxHeaderLen := listWidth - 1
	if len(header) > maxHeaderLen && maxHeaderLen > 3 {
		header = "..." + header[len(header)-maxHeaderLen+3:]
	}

	sb.WriteString(bold)
	sb.WriteString(setFg(a.mainColor))
	sb.WriteString(header)
	sb.WriteString(resetStyle)
	sb.WriteString(clearLine)
	sb.WriteString("\r\n")

	// Calculate list area
	listHeight := a.height - 1 // minus header
	if a.statusBar != "" {
		listHeight--
	}

	filtered := a.filteredEntries()
	n := len(filtered)

	// Adjust offset to keep cursor visible
	if a.cursor < a.offset {
		a.offset = a.cursor
	}
	if a.cursor >= a.offset+listHeight {
		a.offset = a.cursor - listHeight + 1
	}

	for row := 0; row < listHeight; row++ {
		idx := a.offset + row
		sb.WriteString(moveTo(row+2, 1))
		if idx < n {
			entry := filtered[idx]
			name := entry.Name()
			suffix := ""
			if entry.IsDir() {
				suffix = "/"
			}

			icon := ""
			if a.icons {
				icon = getIcon(entry) + " "
			}

			displayName := icon + name + suffix

			// Truncate if needed
			maxLen := listWidth - 1
			if maxLen < 0 {
				maxLen = 0
			}
			if len(displayName) > maxLen {
				displayName = displayName[:maxLen]
			}

			if idx == a.cursor {
				sb.WriteString(setBg(a.mainColor))
				sb.WriteString(setFg(0)) // black text on colored bg
				sb.WriteString(displayName)
				// Pad to fill line width
				padding := maxLen - len(displayName) 
				if padding > 0 {
					sb.WriteString(strings.Repeat(" ", padding))
				}
				sb.WriteString(resetStyle)
			} else {
				if entry.IsDir() {
					sb.WriteString(bold)
				}
				sb.WriteString(displayName)
				if entry.IsDir() {
					sb.WriteString(resetStyle)
				}
			}
		}
		sb.WriteString(clearLine)
	}

	// Status bar
	if a.statusBar != "" {
		sb.WriteString(moveTo(a.height, 1))
		sb.WriteString(dim)
		// Evaluate status bar expression
		status := a.evalStatusBar()
		if len(status) > a.width-1 {
			status = status[:a.width-1]
		}
		sb.WriteString(status)
		sb.WriteString(resetStyle)
		sb.WriteString(clearLine)
	}

	// Preview pane
	if a.preview {
		a.renderPreview(&sb, listWidth, listHeight)
	}

	sb.WriteString(showCursor)
	a.w.WriteString(sb.String())
	a.w.Flush()
}

func (a *App) renderHelp(sb *strings.Builder) {
	sb.WriteString(moveTo(1, 1))
	sb.WriteString(bold)
	sb.WriteString("help")
	sb.WriteString(resetStyle)
	sb.WriteString(clearLine)
	sb.WriteString("\r\n")

	lines := []string{
		"",
		"    arrows, hjkl  Move cursor",
		"    enter         Enter directory",
		"    backspace     Exit directory",
		"    space         Toggle preview",
		"    esc, q        Exit with cd",
		"    ctrl+c        Exit without cd",
		"    /             Fuzzy search",
		"    d, delete     Delete file or dir",
		"    y             Copy to clipboard",
		"    .             Hide hidden files",
		"    ?             Show help",
		"",
	}

	for i, line := range lines {
		row := i + 2
		if row > a.height {
			break
		}
		sb.WriteString(moveTo(row, 1))
		sb.WriteString(line)
		sb.WriteString(clearLine)
	}

	// Clear remaining lines
	for row := len(lines) + 2; row <= a.height; row++ {
		sb.WriteString(moveTo(row, 1))
		sb.WriteString(clearLine)
	}
}

func (a *App) renderPreview(sb *strings.Builder, listWidth, listHeight int) {
	entry := a.currentEntry()

	previewStart := listWidth + 1
	previewWidth := a.width - listWidth

	if a.withBorder {
		// Draw vertical separator
		for row := 1; row <= listHeight+1; row++ {
			sb.WriteString(moveTo(row, listWidth+1))
			sb.WriteString("│")
		}
		previewStart = listWidth + 2
		previewWidth = a.width - listWidth - 1
	}

	if previewWidth <= 0 {
		return
	}

	// Render preview header (name of selected file)
	sb.WriteString(moveTo(1, previewStart))
	if entry != nil {
		headerName := entry.Name()
		if len(headerName) > previewWidth-1 {
			headerName = headerName[:previewWidth-1]
		}
		sb.WriteString(bold)
		sb.WriteString(setFg(a.mainColor))
		sb.WriteString(headerName)
		sb.WriteString(resetStyle)
	}

	// Render preview content
	if entry == nil {
		return
	}

	var lines []string
	fullPath := filepath.Join(a.cwd, entry.Name())

	if entry.IsDir() {
		// List directory contents
		dirEntries, err := os.ReadDir(fullPath)
		if err == nil {
			for _, e := range dirEntries {
				name := e.Name()
				if e.IsDir() {
					name += "/"
				}
				lines = append(lines, name)
			}
		}
	} else {
		// Read file content
		content, err := os.ReadFile(fullPath)
		if err == nil {
			lines = strings.Split(strings.ReplaceAll(string(content), "\r\n", "\n"), "\n")
		}
	}

	// Render lines
	for row := 2; row <= listHeight+1; row++ {
		idx := a.previewScroll + row - 2
		sb.WriteString(moveTo(row, previewStart))
		if idx < len(lines) {
			line := lines[idx]
			// Replace tabs with spaces
			line = strings.ReplaceAll(line, "\t", "    ")
			if len(line) > previewWidth-1 {
				line = line[:previewWidth-1]
			}
			sb.WriteString(line)
		}
		sb.WriteString(clearLine)
	}
}

func (a *App) evalStatusBar() string {
	// Very basic status bar evaluation
	// For now, just return empty
	return ""
}

func (a *App) run() string {
	a.readDir()

	// Clamp cursor initially
	a.clampCursor()

	for {
		a.render()

		key, ch, err := readKey(a.tty)
		if err != nil {
			break
		}

		if a.showHelp {
			a.showHelp = false
			continue
		}

		if a.fuzzyMode {
			switch key {
			case KeyEsc:
				if a.search != "" {
					a.search = ""
					a.cursor = 0
					a.offset = 0
				} else {
					a.fuzzyMode = false
				}
			case KeyEnter:
				a.fuzzyMode = false
				// Navigate into selected entry
				entry := a.currentEntry()
				if entry != nil && entry.IsDir() {
					a.cwd = filepath.Join(a.cwd, entry.Name())
					a.search = ""
					a.fuzzyMode = false
					a.cursor = 0
					a.offset = 0
					a.readDir()
				}
			case KeyBackspace:
				if len(a.search) > 0 {
					// Remove last rune
					_, size := utf8.DecodeLastRuneInString(a.search)
					a.search = a.search[:len(a.search)-size]
					a.cursor = 0
					a.offset = 0
				} else {
					a.fuzzyMode = false
				}
			case KeyUp, KeyK:
				a.cursor--
				a.clampCursor()
			case KeyDown, KeyJ:
				a.cursor++
				a.clampCursor()
			case KeyCtrlC:
				return ""
			case KeyQ:
				if !a.fuzzyMode {
					return a.cwd
				}
				a.search += string(ch)
				a.cursor = 0
				a.offset = 0
			default:
				if ch != 0 {
					a.search += string(ch)
					a.cursor = 0
					a.offset = 0
				}
			}
			continue
		}

		switch key {
		case KeyCtrlC:
			return ""
		case KeyQ, KeyEsc:
			return a.cwd
		case KeyQuestion:
			a.showHelp = !a.showHelp
		case KeyUp, KeyK:
			a.cursor--
			a.clampCursor()
			a.previewScroll = 0
		case KeyDown, KeyJ:
			a.cursor++
			a.clampCursor()
			a.previewScroll = 0
		case KeyShiftUp:
			a.cursor = 0
			a.offset = 0
			a.previewScroll = 0
		case KeyShiftDown:
			filtered := a.filteredEntries()
			a.cursor = len(filtered) - 1
			a.clampCursor()
			a.previewScroll = 0
		case KeyLeft, KeyH:
			// Go up directory
			parent := filepath.Dir(a.cwd)
			if parent != a.cwd {
				prev := filepath.Base(a.cwd)
				a.cwd = parent
				a.search = ""
				a.cursor = 0
				a.offset = 0
				a.readDir()
				// Find prev dir in entries
				for i, e := range a.entries {
					if e.Name() == prev {
						a.cursor = i
						break
					}
				}
				a.clampCursor()
			}
		case KeyBackspace:
			// Go up directory
			parent := filepath.Dir(a.cwd)
			if parent != a.cwd {
				prev := filepath.Base(a.cwd)
				a.cwd = parent
				a.search = ""
				a.cursor = 0
				a.offset = 0
				a.readDir()
				// Find prev dir in entries
				for i, e := range a.entries {
					if e.Name() == prev {
						a.cursor = i
						break
					}
				}
				a.clampCursor()
			}
		case KeyRight, KeyL, KeyEnter:
			entry := a.currentEntry()
			if entry != nil {
				if entry.IsDir() {
					a.cwd = filepath.Join(a.cwd, entry.Name())
					a.search = ""
					a.cursor = 0
					a.offset = 0
					a.readDir()
					a.previewScroll = 0
				} else {
					// Open file with editor
					a.openFile(filepath.Join(a.cwd, entry.Name()))
				}
			}
		case KeySpace:
			a.preview = !a.preview
			a.previewScroll = 0
		case KeySlash:
			a.fuzzyMode = true
			a.search = ""
			a.cursor = 0
			a.offset = 0
		case KeyDot:
			a.showHidden = !a.showHidden
			a.cursor = 0
			a.offset = 0
			a.readDir()
		case KeyD, KeyDelete:
			a.deleteEntry()
		case KeyY:
			a.yankEntry()
		case KeyU:
			a.undoDelete()
		}
	}
	return a.cwd
}

func (a *App) openFile(path string) {
	// Suspend the TUI
	a.w.WriteString(showCursor)
	a.w.WriteString(mainScreen)
	a.w.Flush()
	restoreMode(a.ttyFd, a.origState)

	editor := os.Getenv("WALK_EDITOR")
	if editor == "" {
		editor = os.Getenv("EDITOR")
	}
	if editor == "" {
		editor = "less"
	}

	// Check WALK_OPEN_WITH
	ext := strings.ToLower(filepath.Ext(path))
	openWith := os.Getenv("WALK_OPEN_WITH")
	if openWith != "" {
		// Parse per-extension open commands
		// Format: ext:command,ext:command
		for _, part := range strings.Split(openWith, ",") {
			kv := strings.SplitN(strings.TrimSpace(part), ":", 2)
			if len(kv) == 2 && strings.ToLower(strings.TrimSpace(kv[0])) == ext {
				editor = strings.TrimSpace(kv[1])
				break
			}
		}
	}

	cmd := exec.Command("sh", "-c", editor+" "+shellEscape(path))
	cmd.Stdin = a.tty
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	cmd.Run()

	// Restore TUI
	newState, _ := setRawMode(a.ttyFd)
	if newState != nil {
		a.origState = newState
	}
	a.w.WriteString(altScreen)
	a.w.WriteString(hideCursor)
	a.w.Flush()
}

func (a *App) deleteEntry() {
	entry := a.currentEntry()
	if entry == nil {
		return
	}
	path := filepath.Join(a.cwd, entry.Name())

	removeCmd := os.Getenv("WALK_REMOVE_CMD")
	var err error
	if removeCmd != "" {
		cmd := exec.Command("sh", "-c", removeCmd+" "+shellEscape(path))
		err = cmd.Run()
	} else {
		err = os.RemoveAll(path)
	}

	if err == nil {
		a.deleted = append(a.deleted, DeletedEntry{path: path, dir: a.cwd})
		a.readDir()
		a.clampCursor()
	}
}

func (a *App) undoDelete() {
	// Walk doesn't actually restore deleted files (it's permanent deletion)
	// But per the docs, "undo with u" - so there might be trash-based undo
	// For now, this is a no-op as we can't restore removed files
}

func (a *App) yankEntry() {
	entry := a.currentEntry()
	if entry == nil {
		return
	}
	path := filepath.Join(a.cwd, entry.Name())

	// Try to copy to clipboard
	var cmd *exec.Cmd
	if _, err := exec.LookPath("xclip"); err == nil {
		cmd = exec.Command("xclip", "-selection", "clipboard")
	} else if _, err := exec.LookPath("xsel"); err == nil {
		cmd = exec.Command("xsel", "--clipboard", "--input")
	} else if _, err := exec.LookPath("pbcopy"); err == nil {
		cmd = exec.Command("pbcopy")
	} else if _, err := exec.LookPath("wl-copy"); err == nil {
		cmd = exec.Command("wl-copy")
	}

	if cmd != nil {
		cmd.Stdin = strings.NewReader(path)
		cmd.Run()
	}
}

func shellEscape(s string) string {
	return "'" + strings.ReplaceAll(s, "'", "'\\''") + "'"
}

func getIcon(entry fs.DirEntry) string {
	if entry.IsDir() {
		return ""
	}
	// Return icon based on extension or filename
	name := strings.ToLower(entry.Name())
	ext := strings.ToLower(filepath.Ext(name))

	// Check filename first
	iconMap := getIconMap()
	if icon, ok := iconMap.names[name]; ok {
		return icon
	}
	if icon, ok := iconMap.exts[ext]; ok {
		return icon
	}
	return ""
}

type IconMap struct {
	exts  map[string]string
	names map[string]string
}

var cachedIconMap *IconMap

func getIconMap() *IconMap {
	if cachedIconMap != nil {
		return cachedIconMap
	}
	cachedIconMap = &IconMap{
		exts:  map[string]string{},
		names: map[string]string{},
	}
	// Read icons file from etc/icons
	// The icons file is in etc/icons relative to executable
	exePath, err := os.Executable()
	if err == nil {
		iconsPath := filepath.Join(filepath.Dir(exePath), "etc", "icons")
		loadIconFile(iconsPath, cachedIconMap)
	}
	return cachedIconMap
}

func loadIconFile(path string, m *IconMap) {
	f, err := os.Open(path)
	if err != nil {
		return
	}
	defer f.Close()

	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		line := scanner.Text()
		if strings.HasPrefix(line, "#") || strings.TrimSpace(line) == "" {
			continue
		}
		// Parse: pattern  icon
		parts := strings.Fields(line)
		if len(parts) < 2 {
			continue
		}
		pattern := parts[0]
		icon := parts[1]

		if strings.HasPrefix(pattern, "*.") {
			ext := strings.TrimPrefix(pattern, "*")
			m.exts[ext] = icon
		} else if strings.HasPrefix(pattern, "*") {
			name := strings.TrimPrefix(pattern, "*")
			m.names[strings.ToLower(name)] = icon
		}
	}
}

func main() {
	args := os.Args[1:]

	if len(args) > 0 && args[0] == "--version" {
		fmt.Println(version)
		return
	}

	if len(args) > 0 && args[0] == "--help" {
		printHelp()
		return
	}

	app := &App{
		showHidden: true,
		mainColor:  212, // pink by default
	}

	// Parse flags
	startPath := ""
	for i := 0; i < len(args); i++ {
		switch args[i] {
		case "--icons":
			app.icons = true
		case "--dir-only":
			app.dirOnly = true
		case "--hide-hidden":
			app.showHidden = false
		case "--preview":
			app.preview = true
		case "--with-border":
			app.withBorder = true
		case "--fuzzy":
			app.fuzzy = true
			app.fuzzyMode = true
		default:
			if !strings.HasPrefix(args[i], "--") {
				startPath = args[i]
			}
		}
	}

	// Handle WALK_MAIN_COLOR
	if colorStr := os.Getenv("WALK_MAIN_COLOR"); colorStr != "" {
		var c int
		if _, err := fmt.Sscanf(colorStr, "%d", &c); err == nil {
			app.mainColor = c
		}
	}

	// Handle WALK_STATUS_BAR
	app.statusBar = os.Getenv("WALK_STATUS_BAR")

	// Set starting directory
	if startPath != "" {
		abs, err := filepath.Abs(startPath)
		if err == nil {
			app.cwd = abs
		} else {
			app.cwd = startPath
		}
	} else {
		cwd, err := os.Getwd()
		if err != nil {
			cwd = "/"
		}
		app.cwd = cwd
	}

	// Open TTY
	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		fmt.Fprintln(os.Stderr, "panic: could not open a new TTY:", err)
		os.Exit(1)
	}
	defer tty.Close()

	app.tty = tty
	app.ttyFd = int(tty.Fd())
	app.w = bufio.NewWriter(tty)

	// Set raw mode
	origState, err := setRawMode(app.ttyFd)
	if err != nil {
		fmt.Fprintln(os.Stderr, "Error setting raw mode:", err)
		os.Exit(1)
	}
	app.origState = origState

	// Setup cleanup
	defer func() {
		restoreMode(app.ttyFd, origState)
		app.w.WriteString(showCursor)
		app.w.WriteString(mainScreen)
		app.w.Flush()
	}()

	// Handle signals
	sigCh := make(chan os.Signal, 1)
	signal.Notify(sigCh, syscall.SIGWINCH, syscall.SIGTERM, syscall.SIGINT)
	go func() {
		for sig := range sigCh {
			switch sig {
			case syscall.SIGWINCH:
				app.render()
			case syscall.SIGTERM, syscall.SIGINT:
				restoreMode(app.ttyFd, origState)
				app.w.WriteString(showCursor)
				app.w.WriteString(mainScreen)
				app.w.Flush()
				os.Exit(0)
			}
		}
	}()

	// Switch to alternate screen
	app.w.WriteString(altScreen)
	app.w.WriteString(hideCursor)
	app.w.Flush()

	// Run the app
	result := app.run()

	// Output result
	if result != "" {
		fmt.Println(result)
	}
}

