const version = "v1.13.0"

// Terminal escape codes
const (
	clear          = "\033[H\033[J"
	clearLine      = "\033[K"
	hideCursor     = "\033[?25l"
	showCursor     = "\033[?25h"
	altScreen      = "\033[?1049h"
	mainScreen     = "\033[?1049l"
	resetStyle     = "\033[0m"
	bold           = "\033[1m"
	dim            = "\033[2m"
	reverseVideo   = "\033[7m"
	bracketedPaste = "\033[?2004h"
