const version = "v1.13.0"

// ANSI escape codes
const (
	esc         = "\x1b"
	clear       = "\x1b[H\x1b[2J"
	clearLine   = "\x1b[K"
	hideCursor  = "\x1b[?25l"
	showCursor  = "\x1b[?25h"
	altScreen   = "\x1b[?1049h"
	mainScreen  = "\x1b[?1049l"
	resetStyle  = "\x1b[0m"
	bold        = "\x1b[1m"
	dim         = "\x1b[2m"
	underline   = "\x1b[4m"
	italic      = "\x1b[3m"
