func readEvent(r io.Reader) KeyEvent {
	buf := make([]byte, 1)
	r.Read(buf)
	b := buf[0]

	switch b {
	case 3:
		return KeyEvent{key: keyCtrlC}
	case 8, 127:
		return KeyEvent{key: keyBackspace}
	case 13:
		return KeyEvent{key: keyEnter}
	case 27:
		peek := make([]byte, 1)
		n, _ := r.Read(peek)
		if n == 0 {
			return KeyEvent{key: keyEscape}
		}
		if peek[0] != '[' {
			return KeyEvent{key: keyEscape}
		}
		r.Read(peek)
		switch peek[0] {
		case 'A':
			return KeyEvent{key: keyUp}
		case 'B':
			return KeyEvent{key: keyDown}
		case 'C':
			return KeyEvent{key: keyRight}
		case 'D':
			return KeyEvent{key: keyLeft}
		case '1':
			seq := make([]byte, 3)
			r.Read(seq[:1])
			if seq[0] == ';' {
				r.Read(seq[1:2])
				if seq[1] == '2' {
					r.Read(seq[2:3])
					switch seq[2] {
					case 'A':
						return KeyEvent{key: keyShiftUp}
					case 'B':
						return KeyEvent{key: keyShiftDown}
					}
				}
			}
		case '3':
			r.Read(peek)
			if peek[0] == '~' {
				return KeyEvent{key: keyDelete}
			}
		case '5':
			r.Read(peek) // ~
			return KeyEvent{key: keyShiftUp}
		case '6':
			r.Read(peek) // ~
			return KeyEvent{key: keyShiftDown}
		}
		return KeyEvent{key: keyEscape}
	case ' ':
		return KeyEvent{key: keySpace}
	case '/':
		return KeyEvent{key: keySlash, r: '/'}
	case '.':
		return KeyEvent{key: keyDot, r: '.'}
	case 'd':
		return KeyEvent{key: keyD, r: 'd'}
	case 'y':
		return KeyEvent{key: keyY, r: 'y'}
	case 'u':
		return KeyEvent{key: keyU, r: 'u'}
	case 'q':
		return KeyEvent{key: keyQ, r: 'q'}
	case 'h':
		return KeyEvent{key: keyH, r: 'h'}
	case 'j':
		return KeyEvent{key: keyJ, r: 'j'}
	case 'k':
		return KeyEvent{key: keyK, r: 'k'}
	case 'l':
		return KeyEvent{key: keyL, r: 'l'}
	case '?':
		return KeyEvent{key: keyQuestion, r: '?'}
	default:
		if b >= 32 && b < 128 {
			return KeyEvent{key: keyOther, r: rune(b)}
		}
		if b >= 0x80 {
			var bytes []byte
			bytes = append(bytes, b)
			if b&0xE0 == 0xC0 {
				m := make([]byte, 1)
				r.Read(m)
				bytes = append(bytes, m...)
			} else if b&0xF0 == 0xE0 {
				m := make([]byte, 2)
				r.Read(m)
				bytes = append(bytes, m...)
			} else if b&0xF8 == 0xF0 {
				m := make([]byte, 3)
				r.Read(m)
				bytes = append(bytes, m...)
			}
			ch, _ := utf8.DecodeRune(bytes)
			return KeyEvent{key: keyOther, r: ch}
		}
	}
	return KeyEvent{key: keyOther, r: rune(b)}
}

// App state
type App struct {
	tty       *os.File
	ttyFd     int
	origState *syscall.Termios
	out       *bufio.Writer

	cwd        string
	entries    []fs.DirEntry
	cursor     int
	offset     int

	// Layout
	width  int
	height int

	// Options
	showHidden bool
	dirOnly    bool
	preview    bool
	withBorder bool
	icons      bool
	fuzzy      bool
	fuzzyMode  bool
	search     string

	mainColor int

	showHelp bool

	// Deleted items stack (for undo)
	deleted []string
}

func (a *App) loadDir() {
	entries, err := os.ReadDir(a.cwd)
	if err != nil {
		a.entries = nil
		return
	}
	result := make([]fs.DirEntry, 0, len(entries))
	for _, e := range entries {
		name := e.Name()
		if !a.showHidden && strings.HasPrefix(name, ".") {
			continue
		}
		if a.dirOnly && !e.IsDir() {
			continue
		}
		result = append(result, e)
	}
	a.entries = result
}

func (a *App) filtered() []fs.DirEntry {
	if a.search == "" {
		return a.entries
	}
	pat := strings.ToLower(a.search)
	result := make([]fs.DirEntry, 0)
	for _, e := range a.entries {
		name := strings.ToLower(e.Name())
		if fuzzyMatch(name, pat) {
			result = append(result, e)
		}
	}
	return result
}

func fuzzyMatch(s, pat string) bool {
	j := 0
	for i := 0; i < len(s) && j < len(pat); i++ {
		if s[i] == pat[j] {
			j++
		}
	}
	return j == len(pat)
}

func (a *App) cursorEntry() fs.DirEntry {
	f := a.filtered()
	if len(f) == 0 || a.cursor < 0 || a.cursor >= len(f) {
		return nil
	}
	return f[a.cursor]
}

func (a *App) clamp() {
	f := a.filtered()
	n := len(f)
	if n == 0 {
		a.cursor = 0
		a.offset = 0
		return
	}
	if a.cursor < 0 {
		a.cursor = 0
	}
	if a.cursor >= n {
		a.cursor = n - 1
	}
}

// computeColumns determines the layout for showing entries
func computeColumns(numEntries, listWidth, listHeight int, entries []fs.DirEntry, icons bool, withIcons bool) (numCols, colHeight, cellWidth int) {
	if numEntries == 0 {
		return 1, 0, listWidth
	}

	// Compute max item display width
	maxItemLen := 0
	for _, e := range entries {
		name := e.Name()
		if e.IsDir() {
			name += "/"
		}
		if withIcons {
			name = "  " + name // icon + space
		}
		if len(name) > maxItemLen {
			maxItemLen = len(name)
		}
	}

	// Determine column layout
	// Use algorithm based on observed behavior
	colH := computeColHeight(numEntries, listHeight)
	nc := (numEntries + colH - 1) / colH
	if nc < 1 {
		nc = 1
	}

	// Cell width = maxItemLen + 4 (padding), but at minimum maxItemLen+1
	cw := maxItemLen + 4

	// Cap by terminal width
	maxByWidth := listWidth / cw
	if maxByWidth < 1 {
		maxByWidth = 1
	}
	if nc > maxByWidth {
		nc = maxByWidth
	}

	// Recalculate colHeight with final numCols
	colH = (numEntries + nc - 1) / nc

	return nc, colH, cw
}

// computeColHeight determines the ideal column height based on observed behavior
// The key insight from observation:
// - For small n (<= entries that fit with colH=10): numCols = ceil(n/10) 
// - For larger n: colH grows until it fits or we use more cols based on terminal height
func computeColHeight(n, listH int) int {
	if n <= 0 {
		return 1
	}
	// Base column height: start at 10
	// Observed pattern: transitions happen to keep colH manageable
	// For n <= 100: use ceil(n / ceil(n/10)) which tends to keep colH around 10
	// For larger n: let it grow

	// Target: use minimum numCols such that colH <= max(10, listH*0.4)
	// But from observations, for small n the colH tends to be around 10 or less

	// Simple approach: colH = max(10, ceil(n * listH / (listH * some_factor)))
	// Let's just try to produce the right numCols

	// From the data:
	// listH=49: transitions at n=10,20,30,79,95 (boundaries of numCols 1,2,3,4,5)
	// So maxN for k cols = 10*k for k<=3, then follows a different pattern

	// The maxColH that triggers numCols increase:
	// For numCols=1,2,3: maxColH=10
	// For numCols=4: maxColH = roughly floor(listH * 0.4) 
	// But this gets complicated...

	// Let's use a simplified formula:
	// Compute colH as ceil(n / numCols) where numCols = ceil(n / targetColH)
	// targetColH = min(10, ceil(listH * 0.4))

	targetColH := 10
	if approx := listH * 2 / 5; approx < targetColH {
		targetColH = approx
	}
	if targetColH < 1 {
		targetColH = 1
	}

	numCols := (n + targetColH - 1) / targetColH
	if numCols < 1 {
		numCols = 1
	}

	colH := (n + numCols - 1) / numCols
	return colH
}

func (a *App) render() {
	a.width, a.height = getTermSize(a.ttyFd)

	var sb strings.Builder
	sb.WriteString(hideCursor)

	listWidth := a.width
	previewWidth := 0
	if a.preview {
		listWidth = a.width / 2
		previewWidth = a.width - listWidth
	}

	listHeight := a.height - 1 // minus header row
	if listHeight < 1 {
		listHeight = 1
	}

	// Render header
	sb.WriteString(moveTo(1, 1))
	header := a.cwd
	if a.fuzzyMode || a.search != "" {
		header = a.cwd + "/" + a.search
	}
	if len(header) > listWidth-1 {
		header = "..." + header[len(header)-(listWidth-1)+3:]
	}
	sb.WriteString(bold)
	sb.WriteString(setFg256(a.mainColor))
	sb.WriteString(header)
	sb.WriteString(resetStyle)
	sb.WriteString(clearLine)

	if a.showHelp {
		a.renderHelp(&sb, listWidth, listHeight)
		a.renderRight(&sb, listWidth, previewWidth, listHeight)
		sb.WriteString(showCursor)
		a.out.WriteString(sb.String())
		a.out.Flush()
		return
	}

	filtered := a.filtered()
	n := len(filtered)

	if n == 0 {
		// Show "No files" message
		a.renderEmpty(&sb, listWidth, listHeight)
		a.renderRight(&sb, listWidth, previewWidth, listHeight)
		sb.WriteString(showCursor)
		a.out.WriteString(sb.String())
		a.out.Flush()
		return
	}

	// Determine layout
	numCols, colHeight, cellWidth := computeColumns(n, listWidth, listHeight, filtered, a.icons, a.icons)

	// Determine visible range
	// Items are arranged column-major (top-to-bottom per column, left-to-right)
	// The display shows colHeight rows; if more rows are needed, we scroll.

	// cursor is in which column and row?
	curCol := a.cursor / colHeight
	curRow := a.cursor % colHeight

	_ = curCol
	_ = cellWidth

	// Adjust offset to keep cursor visible
	if a.cursor < a.offset {
		a.offset = a.cursor
	}
	if colHeight > 0 && a.cursor >= a.offset+listHeight*numCols {
		a.offset = a.cursor - listHeight*numCols + numCols
	}

	// Actually, rethink the layout:
	// Items are ordered: col 0 has items 0..colHeight-1, col 1 has items colHeight..2*colHeight-1, etc.
	// The "offset" for multi-col display is the first item index shown (start of first visible row).
	// First visible row = offset / numCols (if items are in row-major order).
	// But items are in COLUMN-MAJOR order.
	// The display shows rows 0..listHeight-1.
	// In each row r, column c, we show item at index: c*colHeight + r + rowOffset.
	// Where rowOffset = first visible row.

	// For simplicity, let's compute:
	// firstVisibleRow = floor(a.cursor_row / listHeight) * listHeight
	// Where cursor_row = a.cursor % colHeight
	// But if colHeight <= listHeight, we show everything with no scrolling.

	if colHeight <= listHeight {
		a.offset = 0
	} else {
		// Scrolling needed
		visibleRows := listHeight
		cursorRow := curRow
		if cursorRow < a.offset {
			a.offset = cursorRow
		}
		if cursorRow >= a.offset+visibleRows {
			a.offset = cursorRow - visibleRows + 1
		}
	}

	// Render rows
	visibleRows := listHeight
	if colHeight < visibleRows {
		visibleRows = colHeight
	}

	// Compute per-column widths for the visible columns
	colWidths := make([]int, numCols)
	for c := 0; c < numCols; c++ {
		maxW := 0
		for r := 0; r < colHeight; r++ {
			idx := c*colHeight + r
			if idx >= n {
				break
			}
			displayLen := a.itemDisplayLen(filtered[idx])
			if displayLen > maxW {
				maxW = displayLen
			}
		}
		colWidths[c] = maxW + 4 // add padding
	}

	for row := 0; row < visibleRows; row++ {
		actualRow := row + a.offset
		sb.WriteString(moveTo(row+2, 1))
		col := 0
		x := 1
		for c := 0; c < numCols; c++ {
			idx := c*colHeight + actualRow
			cw := colWidths[c]
			if x+cw-1 > listWidth {
				cw = listWidth - x + 1
			}
			if cw <= 0 {
				break
			}
			if idx < n {
				entry := filtered[idx]
				displayStr := a.itemDisplay(entry)
				selected := idx == a.cursor

				if selected {
					sb.WriteString(setBg256(a.mainColor))
					sb.WriteString(setFg256(0))
					sb.WriteString(displayStr)
					pad := cw - a.itemDisplayLen(entry) - 1 // -1 because last col has no trailing pad
					if c < numCols-1 {
						pad = cw - a.itemDisplayLen(entry)
					}
					if pad > 0 && x+a.itemDisplayLen(entry)+pad <= listWidth {
						sb.WriteString(strings.Repeat(" ", pad))
					}
					sb.WriteString(resetStyle)
				} else {
					if entry.IsDir() {
						sb.WriteString(bold)
					}
					sb.WriteString(displayStr)
					if entry.IsDir() {
						sb.WriteString(resetStyle)
					}
					if c < numCols-1 {
						// Add padding to align next column
						pad := cw - a.itemDisplayLen(entry)
						if pad > 0 && x+a.itemDisplayLen(entry)+pad <= listWidth {
							sb.WriteString(strings.Repeat(" ", pad))
						}
					}
				}
				x += cw
			} else {
				// Empty slot
				if c < numCols-1 {
					x += cw
				}
			}
			col++
		}
		sb.WriteString(clearLine)
	}

	// Clear remaining rows
	for row := visibleRows; row < listHeight; row++ {
		sb.WriteString(moveTo(row+2, 1))
		sb.WriteString(clearLine)
	}

	// Render right side (preview)
	a.renderRight(&sb, listWidth, previewWidth, listHeight)

	sb.WriteString(showCursor)
	a.out.WriteString(sb.String())
	a.out.Flush()
}

func (a *App) itemDisplay(e fs.DirEntry) string {
	name := e.Name()
	suffix := ""
	if e.IsDir() {
		suffix = "/"
	}
	if a.icons {
		icon := getFileIcon(e)
		return icon + " " + name + suffix
	}
	return name + suffix
}

func (a *App) itemDisplayLen(e fs.DirEntry) int {
	return len(a.itemDisplay(e))
}

func (a *App) renderEmpty(sb *strings.Builder, listWidth, listHeight int) {
	// Show a "No files" dialog box
	msg := "No files"
	boxWidth := len(msg) + 4
	// Center in the list area
	col := (listWidth - boxWidth) / 2
	if col < 1 {
		col = 1
	}
	row := (listHeight + 1) / 2

	sb.WriteString(moveTo(row, col))
	sb.WriteString("╭" + strings.Repeat("─", boxWidth-2) + "╮")
	sb.WriteString(moveTo(row+1, col))
	sb.WriteString("│ " + msg + " │")
	sb.WriteString(moveTo(row+2, col))
	sb.WriteString("╰" + strings.Repeat("─", boxWidth-2) + "╯")

	// Clear surrounding rows
	for r := 2; r <= listHeight+1; r++ {
		sb.WriteString(moveTo(r, 1))
		if r < row || r > row+2 {
			sb.WriteString(clearLine)
		}
	}
}

func (a *App) renderHelp(sb *strings.Builder, listWidth, listHeight int) {
	lines := []string{
		"",
		"    arrows, hjkl  Move cursor",
		"    enter         Enter directory",
		"    backspace     Exit directory",
		"    space         Toggle preview",
		"    esc, q        Exit with cd",
		"    ctrl+c        Exit without cd",
		"    /             Fuzzy search",
		"    d, delete     Delete file or dir",
		"    y             Copy to clipboard",
		"    .             Hide hidden files",
		"    ?             Show help",
		"",
	}

	// Print "help" header in position 1 (which is row 2 of terminal, since header is row 1)
	sb.WriteString(moveTo(2, 1))
	sb.WriteString(bold)
	sb.WriteString("help")
	sb.WriteString(resetStyle)
	sb.WriteString(clearLine)

	for i, line := range lines {
		row := i + 3
		if row > listHeight+1 {
			break
		}
		sb.WriteString(moveTo(row, 1))
		if len(line) > listWidth-1 {
			line = line[:listWidth-1]
		}
		sb.WriteString(line)
		sb.WriteString(clearLine)
	}

	// Clear remaining rows
	for row := len(lines) + 3; row <= listHeight+1; row++ {
		sb.WriteString(moveTo(row, 1))
		sb.WriteString(clearLine)
	}
}

func (a *App) renderRight(sb *strings.Builder, listWidth, previewWidth, listHeight int) {
	if previewWidth <= 0 {
		return
	}

	previewStartCol := listWidth + 1
	contentWidth := previewWidth - 1

	if a.withBorder {
		// Draw vertical border
		for row := 1; row <= listHeight+1; row++ {
			sb.WriteString(moveTo(row, listWidth+1))
			sb.WriteString("│")
		}
		previewStartCol = listWidth + 2
		contentWidth = previewWidth - 2
	}

	if contentWidth <= 0 {
		return
	}

	entry := a.cursorEntry()

	// Header: name of selected
	sb.WriteString(moveTo(1, previewStartCol))
	if entry != nil {
		hdr := entry.Name()
		if len(hdr) > contentWidth {
			hdr = hdr[:contentWidth]
		}
		sb.WriteString(bold)
		sb.WriteString(setFg256(a.mainColor))
		sb.WriteString(hdr)
		sb.WriteString(resetStyle)
	}
	// Clear to end of header line
	for c := previewStartCol + (func() int {
		if entry != nil {
			return len(entry.Name())
		}
		return 0
	}()); c <= a.width; c++ {
	}

	if entry == nil {
		// Clear all preview rows
		for row := 2; row <= listHeight+1; row++ {
			sb.WriteString(moveTo(row, previewStartCol))
			for c := previewStartCol; c <= a.width; c++ {
				sb.WriteString(" ")
			}
		}
		return
	}

	// Get preview content
	fullPath := filepath.Join(a.cwd, entry.Name())
	var lines []string

	if entry.IsDir() {
		dirEntries, err := os.ReadDir(fullPath)
		if err == nil {
			for _, de := range dirEntries {
				name := de.Name()
				if de.IsDir() {
					name += "/"
				}
				lines = append(lines, name)
			}
		}
	} else {
		content, err := os.ReadFile(fullPath)
		if err == nil {
			lines = strings.Split(strings.ReplaceAll(string(content), "\r\n", "\n"), "\n")
		}
	}

	// Render preview lines
	for row := 2; row <= listHeight+1; row++ {
		idx := row - 2
		sb.WriteString(moveTo(row, previewStartCol))
		if idx < len(lines) {
			line := strings.ReplaceAll(lines[idx], "\t", "    ")
			// Strip non-printable chars
			if len(line) > contentWidth {
				line = line[:contentWidth]
			}
			sb.WriteString(line)
		}
		// Clear rest of this row in preview area
		col := previewStartCol
		if idx < len(lines) {
			displayLen := len(lines[idx])
			if displayLen > contentWidth {
				displayLen = contentWidth
			}
			col += displayLen
		}
		for ; col <= a.width; col++ {
			sb.WriteString(" ")
		}
	}
}

func (a *App) openFile(path string) {
	// Suspend TUI
	a.out.WriteString(showCursor)
	a.out.WriteString(mainScreen)
	a.out.Flush()
	restoreTerminal(a.ttyFd, a.origState)

	// Determine opener
	editor := os.Getenv("WALK_EDITOR")
	if editor == "" {
		editor = os.Getenv("EDITOR")
	}
	if editor == "" {
		editor = "less"
	}

	// Check WALK_OPEN_WITH for extension-specific openers
	ext := strings.ToLower(filepath.Ext(path))
	if openWith := os.Getenv("WALK_OPEN_WITH"); openWith != "" {
		for _, part := range strings.Split(openWith, ",") {
			kv := strings.SplitN(strings.TrimSpace(part), ":", 2)
			if len(kv) == 2 && strings.ToLower(strings.TrimSpace(kv[0])) == ext {
				editor = strings.TrimSpace(kv[1])
				break
			}
		}
	}

	var cmd *exec.Cmd
	if editor == "less" {
		cmd = exec.Command("less", path)
	} else {
		cmd = exec.Command("sh", "-c", editor+" "+shellQuote(path))
	}
	cmd.Stdin = a.tty
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	cmd.Run()

	// Restore TUI
	newState, _ := makeRaw(a.ttyFd)
	if newState != nil {
		a.origState = newState
	}
	a.out.WriteString(altScreen)
	a.out.WriteString(hideCursor)
	a.out.Flush()
}

func (a *App) deleteEntry() {
	entry := a.cursorEntry()
	if entry == nil {
		return
	}
	path := filepath.Join(a.cwd, entry.Name())

	var err error
	if removeCmd := os.Getenv("WALK_REMOVE_CMD"); removeCmd != "" {
		cmd := exec.Command("sh", "-c", removeCmd+" "+shellQuote(path))
		err = cmd.Run()
	} else {
		err = os.RemoveAll(path)
	}

	if err == nil {
		a.deleted = append(a.deleted, path)
		a.loadDir()
		a.clamp()
	}
}

func (a *App) yankEntry() {
	entry := a.cursorEntry()
	if entry == nil {
		return
	}
	path := filepath.Join(a.cwd, entry.Name())

	// Try various clipboard commands
	var cmd *exec.Cmd
	if _, err := exec.LookPath("xclip"); err == nil {
		cmd = exec.Command("xclip", "-selection", "clipboard")
	} else if _, err := exec.LookPath("xsel"); err == nil {
		cmd = exec.Command("xsel", "--clipboard", "--input")
	} else if _, err := exec.LookPath("wl-copy"); err == nil {
		cmd = exec.Command("wl-copy")
	} else if _, err := exec.LookPath("pbcopy"); err == nil {
		cmd = exec.Command("pbcopy")
	}

	if cmd != nil {
		cmd.Stdin = strings.NewReader(path)
		cmd.Run()
	}
}

func shellQuote(s string) string {
	return "'" + strings.ReplaceAll(s, "'", "'\\''") + "'"
}

func (a *App) run() string {
	a.loadDir()
	a.clamp()

	for {
		a.render()

		ev := readEvent(a.tty)

		if a.showHelp {
			// Any key dismisses help
			if ev.key == keyQ || ev.key == keyEscape || ev.key == keyQuestion || ev.key == keyCtrlC {
				if ev.key == keyCtrlC {
					return ""
				}
				if ev.key == keyQ || ev.key == keyEscape {
					return a.cwd
				}
			}
			a.showHelp = false
			continue
		}

		if a.fuzzyMode {
			switch ev.key {
			case keyCtrlC:
				return ""
			case keyEscape:
				if a.search != "" {
					a.search = ""
					a.cursor = 0
					a.offset = 0
				} else {
					a.fuzzyMode = false
				}
			case keyEnter:
				entry := a.cursorEntry()
				if entry != nil && entry.IsDir() {
					a.cwd = filepath.Join(a.cwd, entry.Name())
					a.search = ""
					a.fuzzyMode = false
					a.cursor = 0
					a.offset = 0
					a.loadDir()
				} else {
					a.fuzzyMode = false
				}
			case keyBackspace:
				if len(a.search) > 0 {
					_, size := utf8.DecodeLastRuneInString(a.search)
					a.search = a.search[:len(a.search)-size]
					a.cursor = 0
					a.offset = 0
				} else {
					a.fuzzyMode = false
				}
			case keyUp, keyK:
				a.cursor--
				a.clamp()
			case keyDown, keyJ:
				a.cursor++
				a.clamp()
			case keyQ:
				// In fuzzy mode, 'q' is typed into search
				a.search += string(ev.r)
				a.cursor = 0
				a.offset = 0
			default:
				if ev.r != 0 {
					a.search += string(ev.r)
					a.cursor = 0
					a.offset = 0
				}
			}
			continue
		}

		switch ev.key {
		case keyCtrlC:
			return ""
		case keyQ, keyEscape:
			return a.cwd
		case keyQuestion:
			a.showHelp = true
		case keyUp, keyK:
			a.cursor--
			a.clamp()
		case keyDown, keyJ:
			a.cursor++
			a.clamp()
		case keyShiftUp:
			a.cursor = 0
			a.offset = 0
		case keyShiftDown:
			f := a.filtered()
			a.cursor = len(f) - 1
			a.clamp()
		case keyLeft, keyH, keyBackspace:
			parent := filepath.Dir(a.cwd)
			if parent != a.cwd {
				prev := filepath.Base(a.cwd)
				a.cwd = parent
				a.search = ""
				a.cursor = 0
				a.offset = 0
				a.loadDir()
				// Try to find the previous directory
				for i, e := range a.entries {
					if e.Name() == prev {
						a.cursor = i
						break
					}
				}
				a.clamp()
			}
		case keyRight, keyL, keyEnter:
			entry := a.cursorEntry()
			if entry != nil {
				if entry.IsDir() {
					a.cwd = filepath.Join(a.cwd, entry.Name())
					a.search = ""
					a.cursor = 0
					a.offset = 0
					a.loadDir()
					a.clamp()
				} else {
					a.openFile(filepath.Join(a.cwd, entry.Name()))
				}
			}
		case keySpace:
			a.preview = !a.preview
		case keySlash:
			a.fuzzyMode = true
			a.search = ""
			a.cursor = 0
			a.offset = 0
		case keyDot:
			a.showHidden = !a.showHidden
			a.cursor = 0
			a.offset = 0
			a.loadDir()
			a.clamp()
		case keyD, keyDelete:
			a.deleteEntry()
		case keyY:
			a.yankEntry()
		case keyU:
			// Undo - restore last deleted
			// (in this implementation, files can't be restored after RemoveAll)
			// The original shows this as a feature but actual restore depends on WALK_REMOVE_CMD
		}
	}
}

