const version = "v1.13.0"

const (
	seqHideCursor = "\x1b[?25l"
	seqShowCursor = "\x1b[?25h"
	seqAltScreen  = "\x1b[?1049h"
	seqMainScreen = "\x1b[?1049l"
	seqReset      = "\x1b[0m"
	seqBold       = "\x1b[1m"
	seqDim        = "\x1b[2m"
	seqClearLine  = "\x1b[K"
