func main() {
	args := os.Args[1:]

	if len(args) == 1 && args[0] == "--version" {
		fmt.Println(version)
		return
	}

	if len(args) == 1 && args[0] == "--help" {
		printHelp()
		return
	}

	app := &App{
		showHidden: true,
		mainColor:  212,
	}

	startPath := ""
	for _, arg := range args {
		switch arg {
		case "--icons":
			app.icons = true
		case "--dir-only":
			app.dirOnly = true
		case "--hide-hidden":
			app.showHidden = false
		case "--preview":
			app.preview = true
		case "--with-border":
			app.withBorder = true
		case "--fuzzy":
			app.fuzzyMode = true
		default:
			if !strings.HasPrefix(arg, "--") && startPath == "" {
				startPath = arg
			}
		}
	}

	if colorStr := os.Getenv("WALK_MAIN_COLOR"); colorStr != "" {
		var c int
		fmt.Sscanf(colorStr, "%d", &c)
		if c > 0 {
			app.mainColor = c
		}
	}

	if startPath != "" {
		abs, err := filepath.Abs(startPath)
		if err == nil {
			app.cwd = abs
		} else {
			app.cwd = startPath
		}
	} else {
		cwd, err := os.Getwd()
		if err != nil {
			cwd = "/"
		}
		app.cwd = cwd
	}

	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		fmt.Fprintln(os.Stderr, "panic: could not open a new TTY:", err)
		os.Exit(1)
	}
	defer tty.Close()

	app.tty = tty
	app.ttyFd = int(tty.Fd())
	app.out = bufio.NewWriterSize(tty, 65536)

	origState, err := rawMode(app.ttyFd)
	if err != nil {
		fmt.Fprintln(os.Stderr, "error setting raw mode:", err)
		os.Exit(1)
	}
	app.origState = origState

	cleanup := func() {
		restoreTerm(app.ttyFd, origState)
		app.out.WriteString(seqShowCursor)
		app.out.WriteString(seqMainScreen)
		app.out.Flush()
	}
	defer cleanup()

	sigCh := make(chan os.Signal, 1)
	signal.Notify(sigCh, syscall.SIGWINCH, syscall.SIGTERM, syscall.SIGINT)
	go func() {
		for sig := range sigCh {
			switch sig {
			case syscall.SIGWINCH:
				app.render()
			case syscall.SIGTERM, syscall.SIGINT:
				cleanup()
				os.Exit(0)
			}
		}
	}()

	app.out.WriteString(seqAltScreen)
	app.out.WriteString(seqHideCursor)
	app.out.Flush()

	result := app.run()
	if result != "" {
		fmt.Println(result)
	}
}

