type Winsize struct{ Row, Col, Xpixel, Ypixel uint16 }

func termSize(fd int) (w, h int) {
	ws := &Winsize{}
	syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), syscall.TIOCGWINSZ, uintptr(unsafe.Pointer(ws)))
	if ws.Col == 0 {
		return 80, 24
	}
	return int(ws.Col), int(ws.Row)
}

func rawMode(fd int) (*syscall.Termios, error) {
	var old syscall.Termios
	if _, _, e := syscall.Syscall6(syscall.SYS_IOCTL, uintptr(fd), syscall.TCGETS, uintptr(unsafe.Pointer(&old)), 0, 0, 0); e != 0 {
		return nil, e
	}
	s := old
	s.Iflag &^= syscall.BRKINT | syscall.ICRNL | syscall.INPCK | syscall.ISTRIP | syscall.IXON
	s.Oflag &^= syscall.OPOST
	s.Cflag |= syscall.CS8
	s.Lflag &^= syscall.ECHO | syscall.ICANON | syscall.IEXTEN | syscall.ISIG
	s.Cc[syscall.VMIN] = 1
	s.Cc[syscall.VTIME] = 0
	if _, _, e := syscall.Syscall6(syscall.SYS_IOCTL, uintptr(fd), syscall.TCSETS, uintptr(unsafe.Pointer(&s)), 0, 0, 0); e != 0 {
		return nil, e
	}
	return &old, nil
}

func restoreTerm(fd int, s *syscall.Termios) {
	syscall.Syscall6(syscall.SYS_IOCTL, uintptr(fd), syscall.TCSETS, uintptr(unsafe.Pointer(s)), 0, 0, 0)
}

type KeyEvent int

const (
	KNone KeyEvent = iota
	KUp
	KDown
	KLeft
	KRight
	KShiftUp
	KShiftDown
	KEnter
	KBackspace
	KEscape
	KCtrlC
	KSpace
	KChar // printable character
)

type Event struct {
	key KeyEvent
	ch  rune
}

func readEvent(r io.Reader) Event {
	var b [1]byte
	r.Read(b[:])
	switch b[0] {
	case 3:
		return Event{KCtrlC, 0}
	case 8, 127:
		return Event{KBackspace, 0}
	case 13:
		return Event{KEnter, 0}
	case 27:
		var peek [1]byte
		n, _ := r.Read(peek[:])
		if n == 0 {
			return Event{KEscape, 0}
		}
		if peek[0] != '[' {
			return Event{KEscape, 0}
		}
		r.Read(peek[:])
		switch peek[0] {
		case 'A':
			return Event{KUp, 0}
		case 'B':
			return Event{KDown, 0}
		case 'C':
			return Event{KRight, 0}
		case 'D':
			return Event{KLeft, 0}
		case '1':
			var seq [3]byte
			r.Read(seq[:1])
			if seq[0] == ';' {
				r.Read(seq[1:2])
				if seq[1] == '2' {
					r.Read(seq[2:3])
					switch seq[2] {
					case 'A':
						return Event{KShiftUp, 0}
					case 'B':
						return Event{KShiftDown, 0}
					}
				}
			}
		case '3':
			r.Read(peek[:])
			return Event{KChar, 0} // Delete key -> treat as backspace-like? or ignore
		case '5':
			r.Read(peek[:])
			return Event{KShiftUp, 0}
		case '6':
			r.Read(peek[:])
			return Event{KShiftDown, 0}
		}
		return Event{KEscape, 0}
	case 32:
		return Event{KSpace, ' '}
	default:
		ch := rune(b[0])
		if b[0] >= 32 && b[0] < 127 {
			return Event{KChar, ch}
		}
		if b[0] >= 0x80 {
			bytes := []byte{b[0]}
			var extra [3]byte
			var n int
			if b[0]&0xE0 == 0xC0 {
				n = 1
			} else if b[0]&0xF0 == 0xE0 {
				n = 2
			} else if b[0]&0xF8 == 0xF0 {
				n = 3
			}
			if n > 0 {
				r.Read(extra[:n])
				bytes = append(bytes, extra[:n]...)
			}
			ch, _ = utf8.DecodeRune(bytes)
			return Event{KChar, ch}
		}
	}
	return Event{KNone, 0}
}

type App struct {
	tty       *os.File
	ttyFd     int
	origState *syscall.Termios
	out       *bufio.Writer

	cwd     string
	entries []fs.DirEntry
	cursor  int

	// Scroll state for single-column scrolling
	rowOffset int // first visible row in the column layout

	width  int
	height int

	showHidden bool
	dirOnly    bool
	preview    bool
	withBorder bool
	icons      bool
	fuzzyMode  bool
	search     string

	mainColor int

	showHelp bool
}

func (a *App) loadDir() {
	entries, err := os.ReadDir(a.cwd)
	if err != nil {
		a.entries = nil
		return
	}
	result := make([]fs.DirEntry, 0, len(entries))
	for _, e := range entries {
		name := e.Name()
		if !a.showHidden && strings.HasPrefix(name, ".") {
			continue
		}
		if a.dirOnly && !e.IsDir() {
			continue
		}
		result = append(result, e)
	}
	a.entries = result
}

func fuzzyMatch(s, pattern string) bool {
	j := 0
	for i := 0; i < len(s) && j < len(pattern); i++ {
		if s[i] == pattern[j] {
			j++
		}
	}
	return j == len(pattern)
}

// findFirstMatch returns index of first entry matching search, or -1
func (a *App) findFirstMatch() int {
	if a.search == "" {
		return -1
	}
	pat := strings.ToLower(a.search)
	for i, e := range a.entries {
		name := strings.ToLower(e.Name())
		if fuzzyMatch(name, pat) {
			return i
		}
	}
	return -1
}

func (a *App) cursorEntry() fs.DirEntry {
	if a.cursor < 0 || a.cursor >= len(a.entries) {
		return nil
	}
	return a.entries[a.cursor]
}

func (a *App) clamp() {
	n := len(a.entries)
	if n == 0 {
		a.cursor = 0
		return
	}
	if a.cursor < 0 {
		a.cursor = 0
	}
	if a.cursor >= n {
		a.cursor = n - 1
	}
}

// itemName returns the display name for an entry
func (a *App) itemName(e fs.DirEntry) string {
	name := e.Name()
	if e.IsDir() {
		name += "/"
	}
	if a.icons {
		icon := getIcon(e)
		name = icon + " " + name
	}
	return name
}

// computeLayout determines how to display entries in columns
func (a *App) computeLayout(listW, listH int) (numCols, colH, colW int) {
	n := len(a.entries)
	if n == 0 {
		return 1, 0, listW
	}

	// Compute max item name width
	maxItemW := 0
	for _, e := range a.entries {
		w := len(a.itemName(e))
		if w > maxItemW {
			maxItemW = w
		}
	}

	// Cell width = maxItemW + 4 (4 spaces padding between columns)
	cellW := maxItemW + 4

	// Max columns by terminal width (last column doesn't need trailing spaces)
	maxColsByWidth := 1
	if cellW > 0 {
		maxColsByWidth = (listW - maxItemW + cellW - 1) / cellW
		if maxColsByWidth < 1 {
			maxColsByWidth = 1
		}
	}

	// Height-based column count: floor(listW / listH)
	// This is the observed formula that matches the original for typical terminals
	heightBasedMax := listW / listH
	if heightBasedMax < 1 {
		heightBasedMax = 1
	}

	// Number of columns = min(maxColsByWidth, heightBasedMax)
	// But also at least ceil(n/listH) to avoid unnecessary scrolling when possible
	nc := heightBasedMax
	if nc > maxColsByWidth {
		nc = maxColsByWidth
	}
	if nc < 1 {
		nc = 1
	}

	// Column height
	ch := (n + nc - 1) / nc

	return nc, ch, cellW
}

func (a *App) render() {
	a.width, a.height = termSize(a.ttyFd)

	var sb strings.Builder
	sb.WriteString(seqHideCursor)

	listW := a.width
	previewW := 0
	if a.preview {
		listW = a.width / 2
		previewW = a.width - listW
	}

	listH := a.height - 1
	if listH < 1 {
		listH = 1
	}

	// Header (row 1)
	sb.WriteString(seqMoveTo(1, 1))
	if a.showHelp {
		sb.WriteString(seqBold)
		sb.WriteString("help")
		sb.WriteString(seqReset)
		sb.WriteString(seqClearLine)
		a.renderHelp(&sb, listW, listH)
	} else {
		// Path header
		header := a.cwd
		if a.fuzzyMode || a.search != "" {
			header = a.cwd + "/" + a.search
		}
		if len(header) > listW {
			header = "..." + header[len(header)-listW+3:]
		}
		sb.WriteString(seqBold)
		sb.WriteString(seqFg(a.mainColor))
		sb.WriteString(header)
		sb.WriteString(seqReset)
		sb.WriteString(seqClearLine)

		n := len(a.entries)
		if n == 0 {
			a.renderEmpty(&sb, listW, listH)
		} else {
			a.renderEntries(&sb, listW, listH)
		}
	}

	// Preview
	if previewW > 0 {
		a.renderPreview(&sb, listW, previewW, listH)
	}

	sb.WriteString(seqShowCursor)
	a.out.WriteString(sb.String())
	a.out.Flush()
}

func (a *App) renderHelp(sb *strings.Builder, listW, listH int) {
	// Row 1 already has "help" (bold)
	// Rows 2+: empty line, then keybindings
	lines := []string{
		"",
		"    arrows, hjkl  Move cursor",
		"    enter         Enter directory",
		"    backspace     Exit directory",
		"    space         Toggle preview",
		"    esc, q        Exit with cd",
		"    ctrl+c        Exit without cd",
		"    /             Fuzzy search",
		"    d, delete     Delete file or dir",
		"    y             Copy to clipboard",
		"    .             Hide hidden files",
		"    ?             Show help",
		"",
	}
	for i, line := range lines {
		row := i + 2
		if row > listH+1 {
			break
		}
		sb.WriteString(seqMoveTo(row, 1))
		if len(line) > listW {
			line = line[:listW]
		}
		sb.WriteString(line)
		sb.WriteString(seqClearLine)
	}
	for row := len(lines) + 2; row <= listH+1; row++ {
		sb.WriteString(seqMoveTo(row, 1))
		sb.WriteString(seqClearLine)
	}
}

func (a *App) renderEmpty(sb *strings.Builder, listW, listH int) {
	msg := "No files"
	boxW := len(msg) + 4
	col := (listW-boxW)/2 + 1
	if col < 1 {
		col = 1
	}
	row := (listH / 2) + 1

	for r := 2; r <= listH+1; r++ {
		sb.WriteString(seqMoveTo(r, 1))
		if r == row {
			// pad to col
			sb.WriteString(strings.Repeat(" ", col-1))
			sb.WriteString("╭" + strings.Repeat("─", boxW-2) + "╮")
		} else if r == row+1 {
			sb.WriteString(strings.Repeat(" ", col-1))
			sb.WriteString("│ " + msg + " │")
		} else if r == row+2 {
			sb.WriteString(strings.Repeat(" ", col-1))
			sb.WriteString("╰" + strings.Repeat("─", boxW-2) + "╯")
		}
		sb.WriteString(seqClearLine)
	}
}

func (a *App) renderEntries(sb *strings.Builder, listW, listH int) {
	n := len(a.entries)
	numCols, colH, _ := a.computeLayout(listW, listH)

	// Adjust cursor row offset
	cursorCol := a.cursor / colH
	cursorRow := a.cursor % colH
	_ = cursorCol

	// Adjust row offset to keep cursor visible
	if colH <= listH {
		a.rowOffset = 0
	} else {
		if cursorRow < a.rowOffset {
			a.rowOffset = cursorRow
		}
		if cursorRow >= a.rowOffset+listH {
			a.rowOffset = cursorRow - listH + 1
		}
	}

	visibleRows := listH
	if colH < visibleRows {
		visibleRows = colH
	}

	// Compute per-column widths
	colWidths := make([]int, numCols)
	for c := 0; c < numCols; c++ {
		maxW := 0
		for r := 0; r < colH; r++ {
			idx := c*colH + r
			if idx >= n {
				break
			}
			w := len(a.itemName(a.entries[idx]))
			if w > maxW {
				maxW = w
			}
		}
		colWidths[c] = maxW + 4
	}

	for row := 0; row < visibleRows; row++ {
		actualRow := row + a.rowOffset
		sb.WriteString(seqMoveTo(row+2, 1))
		x := 0
		for c := 0; c < numCols; c++ {
			idx := c*colH + actualRow
			cw := colWidths[c]

			// Check if we'd overflow the list width (except last col)
			if c < numCols-1 && x+cw > listW {
				break
			}
			if x >= listW {
				break
			}

			if idx < n {
				entry := a.entries[idx]
				displayName := a.itemName(entry)
				selected := idx == a.cursor

				if selected {
					sb.WriteString(seqBg(a.mainColor))
					sb.WriteString(seqFg(0))
					sb.WriteString(displayName)
					if c < numCols-1 {
						pad := cw - len(displayName)
						if pad < 0 {
							pad = 0
						}
						if x+len(displayName)+pad > listW {
							pad = listW - x - len(displayName)
						}
						if pad > 0 {
							sb.WriteString(strings.Repeat(" ", pad))
						}
					}
					sb.WriteString(seqReset)
				} else {
					if entry.IsDir() {
						sb.WriteString(seqBold)
					}
					sb.WriteString(displayName)
					if entry.IsDir() {
						sb.WriteString(seqReset)
					}
					if c < numCols-1 {
						pad := cw - len(displayName)
						if pad < 0 {
							pad = 0
						}
						if x+len(displayName)+pad > listW {
							pad = listW - x - len(displayName)
						}
						if pad > 0 {
							sb.WriteString(strings.Repeat(" ", pad))
						}
					}
				}
				x += cw
			} else {
				x += cw
			}
		}
		sb.WriteString(seqClearLine)
	}

	// Clear remaining rows
	for row := visibleRows; row < listH; row++ {
		sb.WriteString(seqMoveTo(row+2, 1))
		sb.WriteString(seqClearLine)
	}
}

func (a *App) renderPreview(sb *strings.Builder, listW, previewW, listH int) {
	startCol := listW + 1
	contentW := previewW - 1

	if a.withBorder {
		for row := 1; row <= listH+1; row++ {
			sb.WriteString(seqMoveTo(row, listW+1))
			sb.WriteString("│")
		}
		startCol = listW + 2
		contentW = previewW - 2
	}

	if contentW <= 0 {
		return
	}

	entry := a.cursorEntry()

	// Header
	sb.WriteString(seqMoveTo(1, startCol))
	if entry != nil {
		hdr := entry.Name()
		if len(hdr) > contentW {
			hdr = hdr[:contentW]
		}
		sb.WriteString(seqBold)
		sb.WriteString(seqFg(a.mainColor))
		sb.WriteString(hdr)
		sb.WriteString(seqReset)
	}

	var previewLines []string
	if entry != nil {
		fullPath := filepath.Join(a.cwd, entry.Name())
		if entry.IsDir() {
			if dirEntries, err := os.ReadDir(fullPath); err == nil {
				for _, de := range dirEntries {
					name := de.Name()
					if de.IsDir() {
						name += "/"
					}
					previewLines = append(previewLines, name)
				}
			}
		} else {
			if content, err := os.ReadFile(fullPath); err == nil {
				previewLines = strings.Split(strings.ReplaceAll(string(content), "\r\n", "\n"), "\n")
			}
		}
	}

	for row := 2; row <= listH+1; row++ {
		sb.WriteString(seqMoveTo(row, startCol))
		idx := row - 2
		if idx < len(previewLines) {
			line := strings.ReplaceAll(previewLines[idx], "\t", "    ")
			// Strip non-printable
			if len(line) > contentW {
				line = line[:contentW]
			}
			sb.WriteString(line)
		}
		// Clear rest
		remainingW := a.width - startCol - func() int {
			if idx < len(previewLines) {
				l := strings.ReplaceAll(previewLines[idx], "\t", "    ")
				if len(l) > contentW {
					return contentW
				}
				return len(l)
			}
			return 0
		}()
		if remainingW > 0 {
			sb.WriteString(strings.Repeat(" ", remainingW))
		}
	}
}

func (a *App) openFile(path string) {
	a.out.WriteString(seqShowCursor)
	a.out.WriteString(seqMainScreen)
	a.out.Flush()
	restoreTerm(a.ttyFd, a.origState)

	editor := os.Getenv("WALK_EDITOR")
	if editor == "" {
		editor = os.Getenv("EDITOR")
	}
	if editor == "" {
		editor = "less"
	}

	ext := strings.ToLower(filepath.Ext(path))
	if openWith := os.Getenv("WALK_OPEN_WITH"); openWith != "" {
		for _, part := range strings.Split(openWith, ",") {
			kv := strings.SplitN(strings.TrimSpace(part), ":", 2)
			if len(kv) == 2 && strings.ToLower(strings.TrimSpace(kv[0])) == ext {
				editor = strings.TrimSpace(kv[1])
				break
			}
		}
	}

	var cmd *exec.Cmd
	if editor == "less" || editor == "more" || editor == "cat" {
		cmd = exec.Command(editor, path)
	} else {
		cmd = exec.Command("sh", "-c", editor+" "+shellQuote(path))
	}
	cmd.Stdin = a.tty
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	cmd.Run()

	ns, _ := rawMode(a.ttyFd)
	if ns != nil {
		a.origState = ns
	}
	a.out.WriteString(seqAltScreen)
	a.out.WriteString(seqHideCursor)
	a.out.Flush()
}

func (a *App) deleteEntry() {
	if a.cursor < 0 || a.cursor >= len(a.entries) {
		return
	}
	path := filepath.Join(a.cwd, a.entries[a.cursor].Name())

	var err error
	if removeCmd := os.Getenv("WALK_REMOVE_CMD"); removeCmd != "" {
		cmd := exec.Command("sh", "-c", removeCmd+" "+shellQuote(path))
		err = cmd.Run()
	} else {
		err = os.RemoveAll(path)
	}

	if err == nil {
		a.loadDir()
		a.clamp()
	}
}

func (a *App) yankToClipboard() {
	if a.cursor < 0 || a.cursor >= len(a.entries) {
		return
	}
	path := filepath.Join(a.cwd, a.entries[a.cursor].Name())

	var cmd *exec.Cmd
	for _, clipcmd := range []string{"xclip", "xsel", "wl-copy", "pbcopy"} {
		if _, err := exec.LookPath(clipcmd); err == nil {
			switch clipcmd {
			case "xclip":
				cmd = exec.Command("xclip", "-selection", "clipboard")
			case "xsel":
				cmd = exec.Command("xsel", "--clipboard", "--input")
			default:
				cmd = exec.Command(clipcmd)
			}
			break
		}
	}
	if cmd != nil {
		cmd.Stdin = strings.NewReader(path)
		cmd.Run()
	}
}

func shellQuote(s string) string {
	return "'" + strings.ReplaceAll(s, "'", "'\\''") + "'"
}

func (a *App) run() string {
	a.loadDir()
	a.clamp()

	for {
		a.render()
		ev := readEvent(a.tty)

		if a.showHelp {
			// Any key exits help (except Ctrl+C which exits app)
			if ev.key == KCtrlC {
				return ""
			}
			a.showHelp = false
			if ev.key == KEscape || (ev.key == KChar && (ev.ch == 'q')) {
				return a.cwd
			}
			continue
		}

		if a.fuzzyMode {
			switch ev.key {
			case KCtrlC:
				return ""
			case KEscape:
				a.fuzzyMode = false
				a.search = ""
				a.cursor = 0
				a.rowOffset = 0
			case KEnter:
				entry := a.cursorEntry()
				if entry != nil {
					if entry.IsDir() {
						a.cwd = filepath.Join(a.cwd, entry.Name())
						a.search = ""
						a.fuzzyMode = false
						a.cursor = 0
						a.rowOffset = 0
						a.loadDir()
					} else {
						a.openFile(filepath.Join(a.cwd, entry.Name()))
					}
				}
			case KBackspace:
				if len(a.search) > 0 {
					_, size := utf8.DecodeLastRuneInString(a.search)
					a.search = a.search[:len(a.search)-size]
					// Move cursor to first match
					if idx := a.findFirstMatch(); idx >= 0 {
						a.cursor = idx
					}
				} else {
					a.fuzzyMode = false
				}
			case KUp:
				a.cursor--
				a.clamp()
			case KDown:
				a.cursor++
				a.clamp()
			case KShiftUp:
				a.cursor = 0
			case KShiftDown:
				a.cursor = len(a.entries) - 1
				a.clamp()
			case KSpace:
				a.search += " "
				if idx := a.findFirstMatch(); idx >= 0 {
					a.cursor = idx
				}
			case KChar:
				if ev.ch != 0 {
					a.search += string(ev.ch)
					// Jump cursor to first match
					if idx := a.findFirstMatch(); idx >= 0 {
						a.cursor = idx
					}
				}
			}
			continue
		}

		// Normal mode
		switch ev.key {
		case KCtrlC:
			return ""
		case KEscape:
			return a.cwd
		case KChar:
			switch ev.ch {
			case 'q':
				return a.cwd
			case '?':
				a.showHelp = true
			case 'h':
				a.goUp()
			case 'j':
				a.cursor++
				a.clamp()
			case 'k':
				a.cursor--
				a.clamp()
			case 'l':
				a.goDown()
			case '/':
				a.fuzzyMode = true
				a.search = ""
			case '.':
				a.showHidden = !a.showHidden
				a.cursor = 0
				a.rowOffset = 0
				a.loadDir()
				a.clamp()
			case 'd':
				a.deleteEntry()
			case 'y':
				a.yankToClipboard()
			case 'u':
				// undo - no-op without trash
			}
		case KUp:
			a.cursor--
			a.clamp()
		case KDown:
			a.cursor++
			a.clamp()
		case KLeft:
			a.goUp()
		case KRight:
			a.goDown()
		case KShiftUp:
			a.cursor = 0
			a.rowOffset = 0
		case KShiftDown:
			a.cursor = len(a.entries) - 1
			a.clamp()
		case KEnter:
			a.goDown()
		case KBackspace:
			a.goUp()
		case KSpace:
			a.preview = !a.preview
		}
	}
}

func (a *App) goUp() {
	parent := filepath.Dir(a.cwd)
	if parent == a.cwd {
		return
	}
	prev := filepath.Base(a.cwd)
	a.cwd = parent
	a.search = ""
	a.cursor = 0
	a.rowOffset = 0
	a.loadDir()
	for i, e := range a.entries {
		if e.Name() == prev {
			a.cursor = i
			break
		}
	}
	a.clamp()
}

func (a *App) goDown() {
	entry := a.cursorEntry()
	if entry == nil {
		return
	}
	if entry.IsDir() {
		a.cwd = filepath.Join(a.cwd, entry.Name())
		a.search = ""
		a.cursor = 0
		a.rowOffset = 0
		a.loadDir()
		a.clamp()
	} else {
		a.openFile(filepath.Join(a.cwd, entry.Name()))
	}
}

