package main

import (
	"bufio"
	"fmt"
	"io"
	"io/fs"
	"os"
	"os/exec"
	"os/signal"
	"path/filepath"
	"strings"
	"syscall"
	"unicode/utf8"
	"unsafe"
)

const version = "v1.13.0"

const (
	ansiHideCursor = "\x1b[?25l"
	ansiShowCursor = "\x1b[?25h"
	ansiAltScreen  = "\x1b[?1049h"
	ansiMainScreen = "\x1b[?1049l"
	ansiReset      = "\x1b[0m"
	ansiBold       = "\x1b[1m"
	ansiClearLine  = "\x1b[K"
)

func ansiMoveTo(row, col int) string {
	return fmt.Sprintf("\x1b[%d;%dH", row, col)
}

func ansiFg(c int) string {
	return fmt.Sprintf("\x1b[38;5;%dm", c)
}

func ansiBg(c int) string {
	return fmt.Sprintf("\x1b[48;5;%dm", c)
}

type Winsize struct{ Row, Col, Xpixel, Ypixel uint16 }

func getTermSize(fd int) (w, h int) {
	ws := &Winsize{}
	syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), syscall.TIOCGWINSZ, uintptr(unsafe.Pointer(ws)))
	if ws.Col == 0 {
		return 80, 24
	}
	return int(ws.Col), int(ws.Row)
}

func setRaw(fd int) (*syscall.Termios, error) {
	var old syscall.Termios
	if _, _, e := syscall.Syscall6(syscall.SYS_IOCTL, uintptr(fd), syscall.TCGETS, uintptr(unsafe.Pointer(&old)), 0, 0, 0); e != 0 {
		return nil, e
	}
	s := old
	s.Iflag &^= syscall.BRKINT | syscall.ICRNL | syscall.INPCK | syscall.ISTRIP | syscall.IXON
	s.Oflag &^= syscall.OPOST
	s.Cflag |= syscall.CS8
	s.Lflag &^= syscall.ECHO | syscall.ICANON | syscall.IEXTEN | syscall.ISIG
	s.Cc[syscall.VMIN] = 1
	s.Cc[syscall.VTIME] = 0
	if _, _, e := syscall.Syscall6(syscall.SYS_IOCTL, uintptr(fd), syscall.TCSETS, uintptr(unsafe.Pointer(&s)), 0, 0, 0); e != 0 {
		return nil, e
	}
	return &old, nil
}

func restoreTerm(fd int, s *syscall.Termios) {
	syscall.Syscall6(syscall.SYS_IOCTL, uintptr(fd), syscall.TCSETS, uintptr(unsafe.Pointer(s)), 0, 0, 0)
}

type KeyKind int

const (
	kNone KeyKind = iota
	kUp
	kDown
	kLeft
	kRight
	kShiftUp
	kShiftDown
	kEnter
	kBackspace
	kEsc
	kCtrlC
	kSpace
	kChar
)

type Key struct {
	kind KeyKind
	ch   rune
}

func readKey(r io.Reader) Key {
	var b [1]byte
	if _, err := r.Read(b[:]); err != nil {
		return Key{kCtrlC, 0}
	}
	switch b[0] {
	case 3:
		return Key{kCtrlC, 0}
	case 8, 127:
		return Key{kBackspace, 0}
	case 13:
		return Key{kEnter, 0}
	case 27:
		var p [1]byte
		n, _ := r.Read(p[:])
		if n == 0 {
			return Key{kEsc, 0}
		}
		if p[0] != '[' {
			return Key{kEsc, 0}
		}
		r.Read(p[:])
		switch p[0] {
		case 'A':
			return Key{kUp, 0}
		case 'B':
			return Key{kDown, 0}
		case 'C':
			return Key{kRight, 0}
		case 'D':
			return Key{kLeft, 0}
		case '1':
			var seq [3]byte
			r.Read(seq[:1])
			if seq[0] == ';' {
				r.Read(seq[1:2])
				if seq[1] == '2' {
					r.Read(seq[2:3])
					switch seq[2] {
					case 'A':
						return Key{kShiftUp, 0}
					case 'B':
						return Key{kShiftDown, 0}
					}
				}
			}
		case '3':
			r.Read(p[:]) // consume '~'
			return Key{kBackspace, 0}
		case '5':
			r.Read(p[:])
			return Key{kShiftUp, 0}
		case '6':
			r.Read(p[:])
			return Key{kShiftDown, 0}
		}
		return Key{kEsc, 0}
	case 32:
		return Key{kSpace, ' '}
	}
	if b[0] >= 32 && b[0] < 127 {
		return Key{kChar, rune(b[0])}
	}
	if b[0] >= 0x80 {
		bs := []byte{b[0]}
		var extra [3]byte
		var n int
		if b[0]&0xE0 == 0xC0 {
			n = 1
		} else if b[0]&0xF0 == 0xE0 {
			n = 2
		} else if b[0]&0xF8 == 0xF0 {
			n = 3
		}
		if n > 0 {
			r.Read(extra[:n])
			bs = append(bs, extra[:n]...)
		}
		ch, _ := utf8.DecodeRune(bs)
		return Key{kChar, ch}
	}
	return Key{kNone, 0}
}

type App struct {
	tty       *os.File
	fd        int
	orig      *syscall.Termios
	out       *bufio.Writer
	cwd       string
	entries   []fs.DirEntry
	cursor    int
	rowOffset int // for scrolling when colH > listH
	W, H      int // terminal size
	showHidden bool
	dirOnly    bool
	preview    bool
	border     bool
	icons      bool
	fuzzy      bool // started in fuzzy mode
	searching  bool
	search     string
	color      int
	showHelp   bool
}

func (a *App) load() {
	es, err := os.ReadDir(a.cwd)
	if err != nil {
		a.entries = nil
		return
	}
	out := make([]fs.DirEntry, 0, len(es))
	for _, e := range es {
		if !a.showHidden && strings.HasPrefix(e.Name(), ".") {
			continue
		}
		if a.dirOnly && !e.IsDir() {
			continue
		}
		out = append(out, e)
	}
	a.entries = out
}

func (a *App) clamp() {
	n := len(a.entries)
	if n == 0 {
		a.cursor = 0
		return
	}
	if a.cursor < 0 {
		a.cursor = 0
	}
	if a.cursor >= n {
		a.cursor = n - 1
	}
}

func (a *App) cur() fs.DirEntry {
	if a.cursor >= 0 && a.cursor < len(a.entries) {
		return a.entries[a.cursor]
	}
	return nil
}

// displayName returns the name shown in the file list
func (a *App) displayName(e fs.DirEntry) string {
	name := e.Name()
	if e.IsDir() {
		name += "/"
	}
	if a.icons {
		return fileIcon(e) + " " + name
	}
	return name
}

// fuzzyMatch checks if all chars of pat appear in order in s
func fuzzyMatch(s, pat string) bool {
	j := 0
	for i := 0; i < len(s) && j < len(pat); i++ {
		if s[i] == pat[j] {
			j++
		}
	}
	return j == len(pat)
}

// firstMatch returns index of first entry matching current search
func (a *App) firstMatch() int {
	if a.search == "" {
		return -1
	}
	pat := strings.ToLower(a.search)
	for i, e := range a.entries {
		if fuzzyMatch(strings.ToLower(e.Name()), pat) {
			return i
		}
	}
	return -1
}

// layout computes per-column widths and counts
// Returns: numCols, colHeight, []colWidth
func (a *App) layout(listW int) (int, int, []int) {
	n := len(a.entries)
	if n == 0 {
		return 1, 0, []int{listW}
	}

	// Find max item width for each possible column
	maxItemW := 0
	for _, e := range a.entries {
		w := len(a.displayName(e))
		if w > maxItemW {
			maxItemW = w
		}
	}
	cellW := maxItemW + 4

	// Number of columns: ceil(n/10), capped by width
	nc := (n + 9) / 10
	if nc < 1 {
		nc = 1
	}
	// Max by width: (listW - maxItemW) / cellW + 1
	if cellW > 0 {
		maxW := (listW-maxItemW)/cellW + 1
		if maxW < 1 {
			maxW = 1
		}
		if nc > maxW {
			nc = maxW
		}
	}

	colH := (n + nc - 1) / nc

	// Compute per-column widths
	colWidths := make([]int, nc)
	for c := 0; c < nc; c++ {
		maxW := 0
		for r := 0; r < colH; r++ {
			idx := c*colH + r
			if idx >= n {
				break
			}
			w := len(a.displayName(a.entries[idx]))
			if w > maxW {
				maxW = w
			}
		}
		colWidths[c] = maxW + 4
	}

	return nc, colH, colWidths
}

// listWidth computes the actual display width of the file list
func (a *App) listWidth(termW int) int {
	if !a.preview {
		return termW
	}
	n := len(a.entries)
	if n == 0 {
		return termW / 2
	}
	_, _, colWidths := a.layout(termW)
	total := 0
	for _, w := range colWidths {
		total += w
	}
	// Preview starts at total + 1 (one space separator) or total + 1 (border position)
	// Need to leave room for preview
	previewMinW := 10
	if total+previewMinW >= termW {
		return termW / 2
	}
	return total
}

func (a *App) render() {
	a.W, a.H = getTermSize(a.fd)
	listH := a.H - 1

	var sb strings.Builder
	sb.WriteString(ansiHideCursor)

	lw := a.listWidth(a.W)
	pw := 0
	if a.preview {
		pw = a.W - lw
		if a.border {
			pw -= 1 // for the border character
		}
	}

	// Row 1: header
	sb.WriteString(ansiMoveTo(1, 1))
	if a.showHelp {
		// "help" as header
		sb.WriteString(ansiBold)
		sb.WriteString("help")
		sb.WriteString(ansiReset)
		sb.WriteString(ansiClearLine)
		// Render help content in rows 2+
		a.renderHelp(&sb, lw, listH)
	} else {
		// Path + search as header
		hdr := a.cwd
		if a.searching {
			hdr = a.cwd + "/" + a.search
		}
		// Truncate
		maxHdrW := lw
		if maxHdrW < 3 {
			maxHdrW = 3
		}
		if len(hdr) > maxHdrW {
			hdr = "..." + hdr[len(hdr)-maxHdrW+3:]
		}
		sb.WriteString(ansiBold)
		sb.WriteString(ansiFg(a.color))
		sb.WriteString(hdr)
		sb.WriteString(ansiReset)
		sb.WriteString(ansiClearLine)

		// Render file list in rows 2+
		if len(a.entries) == 0 {
			a.renderEmpty(&sb, lw, listH)
		} else {
			a.renderList(&sb, lw, listH)
		}
	}

	// Preview pane
	if a.preview && pw > 0 {
		a.renderPreview(&sb, lw, pw, listH)
	}

	sb.WriteString(ansiShowCursor)
	a.out.WriteString(sb.String())
	a.out.Flush()
}

func (a *App) renderHelp(sb *strings.Builder, lw, listH int) {
	lines := []string{
		"",
		"    arrows, hjkl  Move cursor",
		"    enter         Enter directory",
		"    backspace     Exit directory",
		"    space         Toggle preview",
		"    esc, q        Exit with cd",
		"    ctrl+c        Exit without cd",
		"    /             Fuzzy search",
		"    d, delete     Delete file or dir",
		"    y             Copy to clipboard",
		"    .             Hide hidden files",
		"    ?             Show help",
		"",
	}
	for i, line := range lines {
		row := i + 2
		if row > listH+1 {
			break
		}
		sb.WriteString(ansiMoveTo(row, 1))
		if len(line) > lw {
			line = line[:lw]
		}
		sb.WriteString(line)
		sb.WriteString(ansiClearLine)
	}
	for row := len(lines) + 2; row <= listH+1; row++ {
		sb.WriteString(ansiMoveTo(row, 1))
		sb.WriteString(ansiClearLine)
	}
}

func (a *App) renderEmpty(sb *strings.Builder, lw, listH int) {
	msg := "No files"
	bw := len(msg) + 4
	col := (lw-bw)/2 + 1
	if col < 1 {
		col = 1
	}
	row := listH/2 + 1
	for r := 2; r <= listH+1; r++ {
		sb.WriteString(ansiMoveTo(r, 1))
		if r == row {
			sb.WriteString(strings.Repeat(" ", col-1))
			sb.WriteString("╭" + strings.Repeat("─", bw-2) + "╮")
		} else if r == row+1 {
			sb.WriteString(strings.Repeat(" ", col-1))
			sb.WriteString("│ " + msg + " │")
		} else if r == row+2 {
			sb.WriteString(strings.Repeat(" ", col-1))
			sb.WriteString("╰" + strings.Repeat("─", bw-2) + "╯")
		}
		sb.WriteString(ansiClearLine)
	}
}

func (a *App) renderList(sb *strings.Builder, lw, listH int) {
	n := len(a.entries)
	nc, colH, colWidths := a.layout(lw)

	// Adjust row offset
	cursorRow := a.cursor % colH
	if colH <= listH {
		a.rowOffset = 0
	} else {
		if cursorRow < a.rowOffset {
			a.rowOffset = cursorRow
		}
		if cursorRow >= a.rowOffset+listH {
			a.rowOffset = cursorRow - listH + 1
		}
	}

	visRows := listH
	if colH < visRows {
		visRows = colH
	}

	for row := 0; row < visRows; row++ {
		ar := row + a.rowOffset
		sb.WriteString(ansiMoveTo(row+2, 1))
		x := 0
		for c := 0; c < nc; c++ {
			idx := c*colH + ar
			cw := colWidths[c]
			if x+cw > lw && c < nc-1 {
				break
			}
			if x >= lw {
				break
			}
			if idx < n {
				e := a.entries[idx]
				dn := a.displayName(e)
				selected := idx == a.cursor

				// Truncate if needed
				available := lw - x
				if c == nc-1 {
					// Last col: no need to pad, just truncate if needed
					if len(dn) > available {
						dn = dn[:available]
					}
				}

				if selected {
					sb.WriteString(ansiBg(a.color))
					sb.WriteString(ansiFg(0))
					sb.WriteString(dn)
					if c < nc-1 {
						pad := cw - len(dn)
						if pad > 0 && x+len(dn)+pad <= lw {
							sb.WriteString(strings.Repeat(" ", pad))
						}
					}
					sb.WriteString(ansiReset)
				} else {
					if e.IsDir() {
						sb.WriteString(ansiBold)
					}
					sb.WriteString(dn)
					if e.IsDir() {
						sb.WriteString(ansiReset)
					}
					if c < nc-1 {
						pad := cw - len(dn)
						if pad > 0 && x+len(dn)+pad <= lw {
							sb.WriteString(strings.Repeat(" ", pad))
						}
					}
				}
				x += cw
			} else {
				x += cw
			}
		}
		sb.WriteString(ansiClearLine)
	}

	// Clear remaining rows
	for row := visRows; row < listH; row++ {
		sb.WriteString(ansiMoveTo(row+2, 1))
		sb.WriteString(ansiClearLine)
	}
}

func (a *App) renderPreview(sb *strings.Builder, lw, pw, listH int) {
	borderCol := lw + 1
	previewCol := lw + 1
	contentW := pw

	if a.border {
		// Draw border
		for r := 1; r <= listH+1; r++ {
			sb.WriteString(ansiMoveTo(r, borderCol))
			sb.WriteString("│")
		}
		previewCol = lw + 2
		contentW = pw - 1
	}

	if contentW <= 0 {
		return
	}

	e := a.cur()

	// Header: preview name
	sb.WriteString(ansiMoveTo(1, previewCol))
	if e != nil {
		hdr := e.Name()
		if len(hdr) > contentW {
			hdr = hdr[:contentW]
		}
		sb.WriteString(ansiBold)
		sb.WriteString(ansiFg(a.color))
		sb.WriteString(hdr)
		sb.WriteString(ansiReset)
	}

	// Preview content
	var lines []string
	if e != nil {
		fullPath := filepath.Join(a.cwd, e.Name())
		if e.IsDir() {
			if des, err := os.ReadDir(fullPath); err == nil {
				for _, de := range des {
					n := de.Name()
					if de.IsDir() {
						n += "/"
					}
					lines = append(lines, n)
				}
			}
		} else {
			if content, err := os.ReadFile(fullPath); err == nil && len(content) < 1024*1024 {
				lines = strings.Split(strings.ReplaceAll(string(content), "\r\n", "\n"), "\n")
			}
		}
	}

	for row := 2; row <= listH+1; row++ {
		sb.WriteString(ansiMoveTo(row, previewCol))
		idx := row - 2
		if idx < len(lines) {
			line := strings.ReplaceAll(lines[idx], "\t", "    ")
			// Remove control characters
			line = strings.Map(func(r rune) rune {
				if r < 32 && r != '\t' {
					return -1
				}
				return r
			}, line)
			if len(line) > contentW {
				line = line[:contentW]
			}
			sb.WriteString(line)
			// Clear to end of line (within this row)
			remaining := contentW - len(line)
			if remaining > 0 {
				sb.WriteString(strings.Repeat(" ", remaining))
			}
		} else {
			sb.WriteString(strings.Repeat(" ", contentW))
		}
	}
}

func (a *App) openFile(path string) {
	a.out.WriteString(ansiShowCursor)
	a.out.WriteString(ansiMainScreen)
	a.out.Flush()
	restoreTerm(a.fd, a.orig)

	editor := os.Getenv("WALK_EDITOR")
	if editor == "" {
		editor = os.Getenv("EDITOR")
	}
	if editor == "" {
		editor = "less"
	}

	ext := strings.ToLower(filepath.Ext(path))
	if openWith := os.Getenv("WALK_OPEN_WITH"); openWith != "" {
		for _, part := range strings.Split(openWith, ",") {
			kv := strings.SplitN(strings.TrimSpace(part), ":", 2)
			if len(kv) == 2 && strings.ToLower(strings.TrimSpace(kv[0])) == ext {
				editor = strings.TrimSpace(kv[1])
				break
			}
		}
	}

	var cmd *exec.Cmd
	if editor == "less" || editor == "more" || editor == "cat" || editor == "bat" {
		cmd = exec.Command(editor, path)
	} else {
		cmd = exec.Command("sh", "-c", editor+" "+shellQ(path))
	}
	cmd.Stdin = a.tty
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	cmd.Run()

	ns, _ := setRaw(a.fd)
	if ns != nil {
		a.orig = ns
	}
	a.out.WriteString(ansiAltScreen)
	a.out.WriteString(ansiHideCursor)
	a.out.Flush()
}

func (a *App) deleteEntry() {
	if a.cursor < 0 || a.cursor >= len(a.entries) {
		return
	}
	path := filepath.Join(a.cwd, a.entries[a.cursor].Name())
	var err error
	if rm := os.Getenv("WALK_REMOVE_CMD"); rm != "" {
		err = exec.Command("sh", "-c", rm+" "+shellQ(path)).Run()
	} else {
		err = os.RemoveAll(path)
	}
	if err == nil {
		a.load()
		a.clamp()
	}
}

func (a *App) yank() {
	if a.cursor < 0 || a.cursor >= len(a.entries) {
		return
	}
	path := filepath.Join(a.cwd, a.entries[a.cursor].Name())
	for _, c := range []struct{ name, arg string }{
		{"xclip", "-selection clipboard"},
		{"xsel", "--clipboard --input"},
		{"wl-copy", ""},
		{"pbcopy", ""},
	} {
		if _, err := exec.LookPath(c.name); err == nil {
			var cmd *exec.Cmd
			if c.arg != "" {
				args := strings.Fields(c.arg)
				cmd = exec.Command(c.name, args...)
			} else {
				cmd = exec.Command(c.name)
			}
			cmd.Stdin = strings.NewReader(path)
			cmd.Run()
			return
		}
	}
}

func shellQ(s string) string {
	return "'" + strings.ReplaceAll(s, "'", "'\\''") + "'"
}

func (a *App) goInto() {
	e := a.cur()
	if e == nil {
		return
	}
	if e.IsDir() {
		a.cwd = filepath.Join(a.cwd, e.Name())
		a.cursor = 0
		a.rowOffset = 0
		a.search = ""
		a.searching = false
		a.load()
		a.clamp()
	} else {
		a.openFile(filepath.Join(a.cwd, e.Name()))
	}
}

func (a *App) goOut() {
	parent := filepath.Dir(a.cwd)
	if parent == a.cwd {
		return
	}
	prev := filepath.Base(a.cwd)
	a.cwd = parent
	a.cursor = 0
	a.rowOffset = 0
	a.search = ""
	a.searching = false
	a.load()
	for i, e := range a.entries {
		if e.Name() == prev {
			a.cursor = i
			break
		}
	}
	a.clamp()
}

func (a *App) run() string {
	a.load()
	a.clamp()

	for {
		a.render()
		k := readKey(a.tty)

		if a.showHelp {
			if k.kind == kCtrlC {
				return ""
			}
			a.showHelp = false
			if k.kind == kEsc || (k.kind == kChar && k.ch == 'q') {
				return a.cwd
			}
			continue
		}

		if a.searching {
			switch k.kind {
			case kCtrlC:
				return ""
			case kEsc:
				a.searching = false
				a.search = ""
				a.cursor = 0
				a.rowOffset = 0
			case kEnter:
				a.goInto()
			case kBackspace:
				if len(a.search) > 0 {
					_, sz := utf8.DecodeLastRuneInString(a.search)
					a.search = a.search[:len(a.search)-sz]
					if idx := a.firstMatch(); idx >= 0 {
						a.cursor = idx
					}
				} else {
					a.searching = false
				}
			case kUp:
				a.cursor--
				a.clamp()
			case kDown:
				a.cursor++
				a.clamp()
			case kShiftUp:
				a.cursor = 0
				a.rowOffset = 0
			case kShiftDown:
				a.cursor = len(a.entries) - 1
				a.clamp()
			case kSpace:
				a.search += " "
				if idx := a.firstMatch(); idx >= 0 {
					a.cursor = idx
				}
			case kChar:
				if k.ch != 0 {
					a.search += string(k.ch)
					if idx := a.firstMatch(); idx >= 0 {
						a.cursor = idx
					}
				}
			}
			continue
		}

		// Normal mode
		switch k.kind {
		case kCtrlC:
			return ""
		case kEsc:
			return a.cwd
		case kUp:
			a.cursor--
			a.clamp()
		case kDown:
			a.cursor++
			a.clamp()
		case kLeft:
			a.goOut()
		case kRight:
			a.goInto()
		case kShiftUp:
			a.cursor = 0
			a.rowOffset = 0
		case kShiftDown:
			a.cursor = len(a.entries) - 1
			a.clamp()
		case kEnter:
			a.goInto()
		case kBackspace:
			a.goOut()
		case kSpace:
			a.preview = !a.preview
		case kChar:
			switch k.ch {
			case 'q':
				return a.cwd
			case '?':
				a.showHelp = true
			case 'h':
				a.goOut()
			case 'j':
				a.cursor++
				a.clamp()
			case 'k':
				a.cursor--
				a.clamp()
			case 'l':
				a.goInto()
			case '/':
				a.searching = true
				a.search = ""
			case '.':
				a.showHidden = !a.showHidden
				a.cursor = 0
				a.rowOffset = 0
				a.load()
				a.clamp()
			case 'd':
				a.deleteEntry()
			case 'y':
				a.yank()
			}
		}
	}
}

