func printHelp() {
	fmt.Printf(`
  walk %s

  Usage: walk [path]

    arrows, hjkl  Move cursor
    enter         Enter directory
    backspace     Exit directory
    space         Toggle preview
    esc, q        Exit with cd
    ctrl+c        Exit without cd
    /             Fuzzy search
    d, delete     Delete file or dir
    y             Copy to clipboard
    .             Hide hidden files
    ?             Show help

  Flags:

    --icons        display icons
    --dir-only     show dirs only
    --hide-hidden  hide hidden files
    --preview      display preview
    --with-border  preview with border
    --fuzzy        fuzzy mode

`, version)
}

func main() {
	args := os.Args[1:]

	if len(args) == 1 && (args[0] == "--version" || args[0] == "-v") {
		fmt.Println(version)
		return
	}
	if len(args) == 1 && (args[0] == "--help" || args[0] == "-h") {
		printHelp()
		return
	}

	app := &App{
		showHidden: true,
		color:      212,
	}

	startPath := ""
	for _, arg := range args {
		switch arg {
		case "--icons":
			app.icons = true
		case "--dir-only":
			app.dirOnly = true
		case "--hide-hidden":
			app.showHidden = false
		case "--preview":
			app.preview = true
		case "--with-border":
			app.border = true
		case "--fuzzy":
			app.fuzzy = true
			app.searching = true
		default:
			if !strings.HasPrefix(arg, "--") && startPath == "" {
				startPath = arg
			}
		}
	}

	if cv := os.Getenv("WALK_MAIN_COLOR"); cv != "" {
		var c int
		fmt.Sscanf(cv, "%d", &c)
		if c > 0 {
			app.color = c
		}
	}

	if startPath != "" {
		if abs, err := filepath.Abs(startPath); err == nil {
			app.cwd = abs
		} else {
			app.cwd = startPath
		}
	} else if cwd, err := os.Getwd(); err == nil {
		app.cwd = cwd
	} else {
		app.cwd = "/"
	}

	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		fmt.Fprintln(os.Stderr, "panic: could not open a new TTY:", err)
		os.Exit(1)
	}
	defer tty.Close()

	app.tty = tty
	app.fd = int(tty.Fd())
	app.out = bufio.NewWriterSize(tty, 1<<16)

	orig, err := setRaw(app.fd)
	if err != nil {
		fmt.Fprintln(os.Stderr, "error setting raw mode:", err)
		os.Exit(1)
	}
	app.orig = orig

	cleanup := func() {
		restoreTerm(app.fd, orig)
		app.out.WriteString(ansiShowCursor)
		app.out.WriteString(ansiMainScreen)
		app.out.Flush()
	}
	defer cleanup()

	sigCh := make(chan os.Signal, 1)
	signal.Notify(sigCh, syscall.SIGWINCH, syscall.SIGTERM, syscall.SIGINT)
	go func() {
		for sig := range sigCh {
			switch sig {
			case syscall.SIGWINCH:
				app.render()
			case syscall.SIGTERM, syscall.SIGINT:
				cleanup()
				os.Exit(0)
			}
		}
	}()

	app.out.WriteString(ansiAltScreen)
	app.out.WriteString(ansiHideCursor)
	app.out.Flush()

	result := app.run()
	if result != "" {
		fmt.Println(result)
	}
