// renderMultiCol renders items in multi-column layout
func renderMultiCol(sb *strings.Builder, items []string, startCol, totalW, maxRow, startRow, highlightColor int) {
	n := len(items)
	if n == 0 {
		return
	}
	// Compute max item width
	maxItemW := 0
	for _, s := range items {
		if len(s) > maxItemW {
			maxItemW = len(s)
		}
	}
	cellW := maxItemW + 4
	// Number of columns
	nc := (n + 9) / 10
	if nc < 1 {
		nc = 1
	}
	maxByWidth := 1
	if cellW > 0 {
		maxByWidth = (totalW-maxItemW)/cellW + 1
		if maxByWidth < 1 {
			maxByWidth = 1
		}
	}
	if nc > maxByWidth {
		nc = maxByWidth
	}
	colH := (n + nc - 1) / nc

	// Per-column widths
	colWidths := make([]int, nc)
	for c := 0; c < nc; c++ {
		maxW := 0
		for r := 0; r < colH; r++ {
			idx := c*colH + r
			if idx >= n {
				break
			}
			if len(items[idx]) > maxW {
				maxW = len(items[idx])
			}
		}
		if c == nc-1 {
